    function showLyoTransitLoader(customText = null, durationMs = 450, onFinished = null) {
      const overlay = document.getElementById('lyo-transit-overlay');
      const subtitle = document.getElementById('lyo-transit-subtitle');
      if (!overlay) return;

      if (!customText) {
        const isTamil = (typeof currentLang !== 'undefined' && currentLang === 'ta');
        const list = isTamil ? LYO_TRANSIT_PHRASES_TA : LYO_TRANSIT_PHRASES_EN;
        customText = list[Math.floor(Math.random() * list.length)];
      }

      subtitle.innerText = customText;
      overlay.classList.add('active');

      const progBar = overlay.querySelector('.lyo-transit-progress-bar');
      if (progBar) {
        progBar.style.animation = 'none';
        void progBar.offsetWidth; // trigger reflow
        progBar.style.animation = `lyoProgressBarRun ${durationMs}ms ease-out forwards`;
      }

      if (durationMs) {
        setTimeout(() => {
          hideLyoTransitLoader();
          if (onFinished) onFinished();
        }, durationMs);
      }
    }

    function hideLyoTransitLoader() {
      const overlay = document.getElementById('lyo-transit-overlay');
      if (overlay) {
        overlay.classList.remove('active');
      }
      try {
        const activeBackdrops = document.querySelectorAll('.modal-backdrop.active, .popup-overlay.active');
        activeBackdrops.forEach(m => {
          if (m && m.id !== 'success-order-modal' && m.id !== 'admin-order-success-modal' && m.id !== 'custom-confirm-modal' && m.id !== 'custom-alert-modal') {
            m.classList.remove('active');
            if (m.style && m.style.display !== 'none') m.style.display = 'none';
          }
        });
      } catch(e) {}
    }

    function showLoadingModal(msg) {
      showLyoTransitLoader(msg, 0);
    }

    function hideLoadingModal() {
      hideLyoTransitLoader();
    }

    function showScreen(screenId) {
      try {
        if (typeof currentScreen !== 'undefined' && currentScreen === screenId) {
          const activeEl = document.getElementById(screenId);
          if (activeEl && activeEl.classList.contains('active')) {
            return;
          }
        }

        if (screenId !== 'screen-lyo-ai' && window.visualViewport && window.lyoAiViewportResizeListener) {
          try {
            window.visualViewport.removeEventListener('resize', window.lyoAiViewportResizeListener);
          } catch(e) {}
          window.lyoAiViewportResizeListener = null;
          const composeBox = document.querySelector('#lyo-ai-compose-box');
          if (composeBox) {
            composeBox.style.transform = 'translateY(0)';
          }
        }

        if (typeof dismissToast === 'function' && typeof toastShowTime !== 'undefined' && Date.now() - toastShowTime > 300) {
          const container = document.getElementById('toast-container');
          if (container && container.classList.contains('show')) {
            dismissToast();
          }
        }

        if (screenId === 'screen-admin') {
          debugLog("[Route Guard] Intercepted navigation to screen-admin. Verifying local session...");
          const adminSession = typeof getAdminSession === 'function' ? getAdminSession() : null;
          const hasAdminSession = !!(adminSession && adminSession.loggedIn);

          if (!hasAdminSession) {
            console.error("[Route Guard] Access DENIED: No active local admin session.");
            showToast("அனுமதி மறுக்கப்பட்டது! நிர்வாகி உள்நுழையவும் / Access Denied. Please login as admin.", "error");
            setTimeout(() => showScreen('screen-login'), 50);
            return;
          }

          if (typeof firebase !== 'undefined' && firebase.auth) {
            const user = firebase.auth().currentUser;
            if (!user || user.isAnonymous) {
              debugLog("[Route Guard] Operating under active local admin session.");
            } else {
              (async () => {
                const finalUser = firebase.auth().currentUser;
                if (!finalUser || finalUser.isAnonymous) {
                  return;
                }

                window._verifiedAdminUids = window._verifiedAdminUids || new Set();
                if (window._verifiedAdminUids.has(finalUser.uid)) {
                  return;
                }

              try {
                let docSnap = await db.collection('ek_admin_accounts').doc(finalUser.uid).get();
                let adminData = null;
                if (docSnap.exists) {
                  adminData = docSnap.data();
                } else {
                  const adminEmail = finalUser.email;
                  const phoneStr = adminEmail ? adminEmail.replace('admin_', '').split('@')[0] : '';
                  const qSnap = await db.collection('ek_admin_accounts').where('email', '==', adminEmail).get();
                  let foundDoc = null;
                  if (!qSnap.empty) {
                    foundDoc = qSnap.docs[0];
                  } else if (phoneStr) {
                    const qSnapPhone = await db.collection('ek_admin_accounts').where('phone', '==', phoneStr).get();
                    if (!qSnapPhone.empty) {
                      foundDoc = qSnapPhone.docs[0];
                    }
                  }

                  if (foundDoc) {
                    adminData = foundDoc.data();
                    adminData.id = finalUser.uid;
                    adminData.uid = finalUser.uid;
                    await db.collection('ek_admin_accounts').doc(finalUser.uid).set(adminData);
                    debugLog("[Route Guard Background] Self-healed UID mapping for admin:", finalUser.uid);
                  } else {
                    const matchedFallback = DEFAULT_FALLBACK_ADMINS.find(fa => fa.email === adminEmail || fa.phone === phoneStr);
                    if (matchedFallback) {
                      adminData = {
                        ...matchedFallback,
                        id: finalUser.uid,
                        uid: finalUser.uid,
                        active: true,
                        createdAt: new Date().toISOString()
                      };
                      await db.collection('ek_admin_accounts').doc(finalUser.uid).set(adminData);
                      debugLog("[Route Guard Background] Initialized fallback admin account in Firestore for UID:", finalUser.uid);
                    }
                  }
                }

                if (adminData) {
                  if ((adminData.role !== 'admin' && adminData.role !== 'superadmin' && adminData.role !== 'ADMIN' && adminData.role !== 'SUPERADMIN') || adminData.active === false) {
                    console.error("[Route Guard Background] Access DENIED: Admin account inactive or not admin/superadmin.");
                    showToast("உரிமம் மறுக்கப்பட்டது! / Admin account inactive.", "error");
                    showScreen('screen-login');
                  } else {
                    window._verifiedAdminUids = window._verifiedAdminUids || new Set();
                    window._verifiedAdminUids.add(finalUser.uid);
                    debugLog("[Route Guard Background] Admin credentials verified successfully ✓ UID:", finalUser.uid);
                  }
                } else {
                  let activeCount = 0;
                  try {
                    const qSnap = await db.collection('ek_admin_accounts').get();
                    qSnap.forEach(doc => {
                      const data = doc.data();
                      if (data && data.active !== false) {
                        activeCount++;
                      }
                    });
                  } catch (e) {
                    console.warn("Could not query admin count in route guard:", e);
                  }

                  if (activeCount === 0) {
                    debugLog("[Route Guard Background] Succeeded: Zero active admin accounts in Firestore. Checking and showing superadmin setup.");
                    await checkAndShowSuperAdminSetup();
                  } else {
                    console.error(`[Route Guard Background] Access DENIED: No doc in 'ek_admin_accounts' for UID: ${finalUser.uid}`);
                    showToast("அங்கீகாரம் இல்லாத கணக்கு! / Admin UID not in database.", "error");
                    showScreen('screen-login');
                  }
                }
              } catch (err) {
                console.warn("[Route Guard Background] Firestore check bypassed due to network/offline status:", err);
              }
            })();
          }
        }
      }

        if (typeof currentScreen !== 'undefined' && currentScreen !== screenId && currentScreen !== 'screen-splash' && screenId !== 'screen-splash') {
          // showLyoTransitLoader(null, 450); // Bypassed for instant tab navigation
        }

        if (!isNavigatingBack && typeof currentScreen !== 'undefined' && currentScreen !== screenId && currentScreen !== 'screen-splash') {
          if (screenHistory.length === 0 || screenHistory[screenHistory.length - 1] !== currentScreen) {
            screenHistory.push(currentScreen);
          }
        }

        if (screenId !== 'screen-track') {
          try { clearRiderAnimation(); } catch(e) { console.warn('clearRiderAnimation failed', e); }
        }

        if (screenId !== 'screen-track' && typeof trackerLeafletMap !== 'undefined' && trackerLeafletMap) {
          try {
            trackerLeafletMap.remove();
          } catch(e) { console.warn(e); }
          trackerLeafletMap = null;
          if (typeof riderMarker !== 'undefined') riderMarker = null;
          if (typeof storeMarker !== 'undefined') storeMarker = null;
          if (typeof customerMarker !== 'undefined') customerMarker = null;
        }
        if (screenId !== 'screen-delivery') {
          if (window.riderLiveCoordInterval) {
            clearInterval(window.riderLiveCoordInterval);
            window.riderLiveCoordInterval = null;
          }
          if (window.activeGpsSimulationInterval) {
            clearInterval(window.activeGpsSimulationInterval);
            window.activeGpsSimulationInterval = null;
          }
        }
        if (screenId !== 'screen-admin' && typeof deliveryLeafletMap !== 'undefined' && deliveryLeafletMap) {
          try {
            deliveryLeafletMap.remove();
          } catch(e) { console.warn(e); }
          deliveryLeafletMap = null;
          if (typeof deliveryRiderMarker !== 'undefined') deliveryRiderMarker = null;
          if (typeof deliveryStoreMarker !== 'undefined') deliveryStoreMarker = null;
          if (typeof deliveryCustomerMarker !== 'undefined') deliveryCustomerMarker = null;
        }

        document.querySelectorAll('.screen').forEach(s => s.classList.remove('active', 'screen-transitioning'));
        const target = document.getElementById(screenId);
        if (target) {
          target.scrollTop = 0; // RESET scroll to top of screen on view transition to ensure native behavior
          target.scrollLeft = 0; // RESET horizontal scroll offset
          const appContainer = document.querySelector('.app-container');
          if (appContainer) appContainer.scrollLeft = 0;
          document.body.scrollLeft = 0;
          document.documentElement.scrollLeft = 0;
          target.classList.add('active', 'screen-transitioning');
          currentScreen = screenId;

          setTimeout(() => {
            target.classList.remove('screen-transitioning');
          }, 25);
        } else {
          console.error(`[showScreen] Target screen "${screenId}" not found in DOM!`);
        }

        const bottomNav = document.getElementById('app-bottom-nav');
        if (bottomNav) {
          if (['screen-splash', 'screen-onboarding', 'screen-login', 'screen-register', 'screen-admin', 'screen-delivery'].includes(screenId)) {
            bottomNav.style.display = 'none';
          } else {
            bottomNav.style.display = 'flex';
          }
        }

        try {
          if (screenId === 'screen-home') {
            renderHomeScreen();
            const settings = getSettings();
            if (settings.leaveMode && !sessionStorage.getItem('leave_popup_shown')) {
              sessionStorage.setItem('leave_popup_shown', 'true');
              showCustomAlert(
                currentLang === 'ta' ? "🌴 விடுமுறை அறிவிப்பு" : "🌴 Holiday / Leave Notice",
                settings.leaveNotice || (currentLang === 'ta' ? "மன்னிக்கவும்! கடை தற்காலிகமாக விடுமுறையில் உள்ளது. ஆர்டர் செய்ய இயலாது." : "Sorry, the shop is currently closed on holiday. Ordering is temporarily paused.")
              );
            }
          } else if (screenId === 'screen-login') {
            try { enterCustomerLogin(); } catch(e) {}
            prefillLoginCredentials();
          } else if (screenId === 'screen-register') {
            const storedRef = sessionStorage.getItem('ek_referred_by_code');
            if (storedRef && document.getElementById('reg-referral')) {
              document.getElementById('reg-referral').value = storedRef;
            }
          } else if (screenId === 'screen-cart') {
            renderCartScreen();
          } else if (screenId === 'screen-track') {
            renderTrackerScreen();
          } else if (screenId === 'screen-profile') {
            renderProfileScreen();
          } else if (screenId === 'screen-admin') {
            renderAdminDashboard();
            initSectionCollapse('categories', 'collapsed');
            initSectionCollapse('carousel', 'collapsed');
            initSectionCollapse('upi-config', 'collapsed');
          } else if (screenId === 'screen-delivery') {
            renderDeliveryScreen();
          } else if (screenId === 'screen-lyo-ai') {
            initLyoAiChat();
            setTimeout(() => {
              const lyoInput = document.getElementById('lyo-ai-input');
              if (lyoInput) {
                const msgStream = document.getElementById('lyo-ai-messages');
                if (msgStream) {
                  msgStream.scrollTop = msgStream.scrollHeight;
                }
              }
            }, 100);

            if (window.visualViewport && !window.lyoAiViewportResizeListener) {
              window.lyoAiViewportResizeListener = function() {
                const composeBox = document.querySelector('#lyo-ai-compose-box');
                if (composeBox) {
                  const keyboardHeight = window.innerHeight - window.visualViewport.height;
                  composeBox.style.transform = keyboardHeight > 100 ? `translateY(-${keyboardHeight}px)` : 'translateY(0)';
                }
              };
              window.visualViewport.addEventListener('resize', window.lyoAiViewportResizeListener);
            }
          } else if (screenId === 'screen-offers') {
            updateClaimBoxState();
          }
        } catch (renderErr) {
          console.error(`[showScreen] Render failed for "${screenId}":`, renderErr);
          if (typeof showToast === 'function') {
            showToast('⚠️ Display issue — pull to refresh', 'error');
          }
        }
      } catch (criticalErr) {
        console.error('[showScreen] CRITICAL failure:', criticalErr);
      }
    }

    function showTab(tabName) {
      document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
      if (tabName === 'tab-home') {
        const homeBtn = document.getElementById('nav-btn-home') || document.querySelector('.nav-tab:nth-child(1)');
        if (homeBtn) homeBtn.classList.add('active');
        showScreen('screen-home');
      } else if (tabName === 'tab-cart') {
        const cartBtn = document.getElementById('nav-btn-cart') || document.querySelector('.nav-tab:nth-child(2)');
        if (cartBtn) cartBtn.classList.add('active');
        showScreen('screen-cart');
      } else if (tabName === 'tab-lyo-ai') {
        const lyoBtn = document.getElementById('lyo-ai-nav-btn');
        if (lyoBtn) lyoBtn.classList.add('active');
        showScreen('screen-lyo-ai');
        updateLyoDeliveryBanner();
        if (typeof initLyoAiChat === 'function') initLyoAiChat();
        if (typeof updateLyoDraftCartBar === 'function') updateLyoDraftCartBar();

        if (typeof firebase !== 'undefined' && firebase.auth) {
          const authUser = firebase.auth().currentUser;
          if (authUser) {
            debugLog("[Diagnostic] auth UID when chatbot opens: " + authUser.uid);
          } else {
            console.warn("[Diagnostic] auth UID when chatbot opens: None (User is signed out or anonymous guest). Reason: Firebase currentUser is null or anonymous.");
          }
        } else {
          console.error("[Diagnostic] auth UID when chatbot opens: None. Reason: Firebase SDK is not loaded.");
        }

      } else if (tabName === 'tab-track') {
        if (typeof getActiveSession === 'function' && !getActiveSession() && !selectedTrackOrderId) {
          showToast(currentLang === 'ta' ? "முன்னோட்டமிட முதலில் உள்நுழையவும்! 🔐" : "Please login or register first to track orders! 🔐", "warning");
          showScreen('screen-login');
          return;
        }
        const trackBtn = document.getElementById('nav-btn-track') || document.querySelector('.nav-tab:nth-child(4)');
        if (trackBtn) trackBtn.classList.add('active');
        showScreen('screen-track');
      } else if (tabName === 'tab-profile') {
        if (typeof getActiveSession === 'function' && !getActiveSession()) {
          showToast(currentLang === 'ta' ? "உள்நுழையவும் அல்லது புதிய அக்கவுண்ட் உருவாக்கவும்! 🔐" : "Please login or register first to manage your profile! 🔐", "warning");
          showScreen('screen-login');
          return;
        }
        const profileBtn = document.getElementById('nav-btn-profile') || document.querySelector('.nav-tab:nth-child(5)');
        if (profileBtn) profileBtn.classList.add('active');
        showScreen('screen-profile');
      }
    }

    // Declarative Back Navigation Configuration Map
    const BACK_BEHAVIOR = {
      'screen-admin': {
        type: 'double-press-action',
        timeoutMs: 2000,
        stateKey: '_adminBackPressTime',
        toastMessage: () => (typeof currentLang !== 'undefined' && currentLang === 'ta')
          ? "மீண்டும் Back அழுத்தி Logout செய்யவும்"
          : "Press back again to logout",
        action: () => {
          if (typeof adminLogout === 'function') {
            adminLogout();
          }
        }
      },
      'screen-home': {
        type: 'double-press-action',
        timeoutMs: 2000,
        stateKey: '_homeBackPressTime',
        toastMessage: () => (typeof currentLang !== 'undefined' && currentLang === 'ta')
          ? "வெளியேற மீண்டும் பின்னால் அழுத்தவும்"
          : "Press back again to exit",
        action: () => {
          const isTa = (typeof currentLang !== 'undefined' && currentLang === 'ta');
          const title = isTa ? "வெளியேறு / Exit App" : "Exit App";
          const msg = isTa ? "செயலியை மூட விரும்புகிறீர்களா?" : "Are you sure you want to exit the app?";
          const okText = isTa ? "வெளியேறு" : "Exit";
          const cancelText = isTa ? "ரத்து" : "Cancel";

          if (typeof showCustomConfirm === 'function') {
            showCustomConfirm(title, msg, () => {
              if (typeof AndroidStorage !== 'undefined' && typeof AndroidStorage.exitApp === 'function') {
                AndroidStorage.exitApp();
              } else if (typeof AndroidStorage !== 'undefined' && typeof AndroidStorage.minimizeApp === 'function') {
                AndroidStorage.minimizeApp();
              }
            }, null, okText, cancelText);
          }
        }
      },
      'screen-splash': {
        type: 'ignore'
      },
      'default': {
        type: 'navigate-home'
      }
    };
    window.BACK_BEHAVIOR = BACK_BEHAVIOR;

    function handleAndroidBack() {
      try {
        // 1. Check if any modals, popups, bottom sheets, side menus, or custom confirm/alert dialogs are visible
        const allModals = Array.from(document.querySelectorAll('.modal-backdrop, .modal, .popup-overlay, #custom-confirm-modal, #custom-alert-modal, .side-menu, .drawer, .bottom-sheet'));
        const activeModal = allModals.find(m => {
          if (!m) return false;
          const display = window.getComputedStyle(m).getPropertyValue('display');
          const visibility = window.getComputedStyle(m).getPropertyValue('visibility');
          const opacity = window.getComputedStyle(m).getPropertyValue('opacity');
          return display !== 'none' && visibility !== 'hidden' && opacity !== '0';
        });

        if (activeModal) {
          const mid = activeModal.id;
          if (mid === 'product-detail-modal') {
            if (typeof closeProductModalDetail === 'function') closeProductModalDetail();
            else activeModal.style.display = 'none';
          } else if (mid === 'admin-add-product-modal') {
            if (typeof closeAdminAddProductModalDetail === 'function') closeAdminAddProductModalDetail();
            else if (typeof closeAdminAddProductModal === 'function') closeAdminAddProductModal();
            else activeModal.style.display = 'none';
          } else if (mid === 'admin-edit-product-modal') {
            if (typeof closeAdminEditProductModalDetail === 'function') closeAdminEditProductModalDetail();
            else if (typeof closeAdminEditProductModal === 'function') closeAdminEditProductModal();
            else activeModal.style.display = 'none';
          } else if (mid === 'developer-info-modal') {
            if (typeof closeDeveloperModalDetail === 'function') closeDeveloperModalDetail();
            else if (typeof closeDeveloperModal === 'function') closeDeveloperModal();
            else activeModal.style.display = 'none';
          } else if (mid === 'privacy-policy-modal') {
            if (typeof closePrivacyPolicyDetail === 'function') closePrivacyPolicyDetail();
            else activeModal.style.display = 'none';
          } else if (mid === 'print-preview-modal') {
            if (typeof closePrintPreviewModalDetail === 'function') closePrintPreviewModalDetail();
            else activeModal.style.display = 'none';
          } else if (mid === 'order-cancel-modal') {
            if (typeof closeOrderCancelModalDetail === 'function') closeOrderCancelModalDetail();
            else activeModal.style.display = 'none';
          } else if (mid === 'forgot-password-modal') {
            if (typeof hideForgotPasswordModal === 'function') hideForgotPasswordModal();
            else activeModal.style.display = 'none';
          } else if (mid === 'customer-order-detail-modal') {
            if (typeof closeCustomerOrderDetailModalDetail === 'function') closeCustomerOrderDetailModalDetail();
            else activeModal.style.display = 'none';
          } else if (mid === 'lightbox-modal') {
            if (typeof closeLightboxModal === 'function') closeLightboxModal();
            else activeModal.style.display = 'none';
          } else if (mid === 'notification-center-modal') {
            if (typeof closeNotificationCenter === 'function') closeNotificationCenter();
            else activeModal.style.display = 'none';
          } else if (mid === 'whatsapp-share-modal') {
            if (typeof closeWhatsAppShareModal === 'function') closeWhatsAppShareModal();
            else activeModal.style.display = 'none';
          } else if (mid === 'manual-location-pin-modal') {
            if (typeof closeManualPinModal === 'function') closeManualPinModal();
            else activeModal.style.display = 'none';
          } else if (mid === 'add-confirmation-modal') {
            if (typeof closeAddConfirmationModal === 'function') closeAddConfirmationModal();
            else activeModal.style.display = 'none';
          } else {
            activeModal.style.display = 'none';
            activeModal.classList.remove('active');
          }
          return true; // Handled modal dismissal
        }

        // 2. Lookup currentScreen behavior in declarative BACK_BEHAVIOR map
        const screenKey = (typeof currentScreen !== 'undefined' && currentScreen) ? currentScreen : 'screen-home';
        const behavior = BACK_BEHAVIOR[screenKey] || BACK_BEHAVIOR['default'];

        if (behavior.type === 'double-press-action') {
          const now = Date.now();
          const lastTime = window[behavior.stateKey] || 0;
          if (lastTime && (now - lastTime < (behavior.timeoutMs || 2000))) {
            window[behavior.stateKey] = 0;
            behavior.action();
          } else {
            window[behavior.stateKey] = now;
            const msg = typeof behavior.toastMessage === 'function' ? behavior.toastMessage() : behavior.toastMessage;
            if (typeof showToast === 'function') {
              showToast(msg, 'info');
            }
          }
          return true;
        }

        if (behavior.type === 'navigate-home') {
          screenHistory = [];
          if (typeof showTab === 'function') {
            showTab('tab-home');
          } else if (typeof showScreen === 'function') {
            showScreen('screen-home');
          }
          return true;
        }

        if (behavior.type === 'ignore') {
          return true;
        }

        return false;
      } catch (err) {
        console.error("Error in handleAndroidBack:", err);
        return false;
      }
    }
    window.handleAndroidBack = handleAndroidBack;

    function togglePasswordVisibility(id, iconEl) {
      const inp = document.getElementById(id);
      if (!inp) return;
      if (inp.type === 'password') {
        inp.type = 'text';
        if (iconEl) {
          iconEl.innerText = '🙈';
        } else {
          const parent = inp.parentElement;
          if (parent) {
            const eye = parent.querySelector('span, i');
            if (eye) eye.innerText = '🙈';
          }
        }
      } else {
        inp.type = 'password';
        if (iconEl) {
          iconEl.innerText = '👁️';
        } else {
          const parent = inp.parentElement;
          if (parent) {
            const eye = parent.querySelector('span, i');
            if (eye) eye.innerText = '👁️';
          }
        }
      }
    }

    function sha256_js(ascii) {
      function rightRotate(value, amount) {
        return (value >>> amount) | (value << (32 - amount));
      }
      var mathPow = Math.pow;
      var maxWord = mathPow(2, 32);
      var lengthProperty = 'length';
      var i, j;
      var result = '';
      var words = [];
      var asciiLength = ascii[lengthProperty];
      var hash = sha256_js.h = sha256_js.h || [];
      var k = sha256_js.k = sha256_js.k || [];
      var primeCounter = k[lengthProperty];
      var isComposite = {};
      for (var candidate = 2; primeCounter < 64; candidate++) {
        if (!isComposite[candidate]) {
          for (i = 0; i < 313; i += candidate) {
            isComposite[i] = 1;
          }
          hash[primeCounter] = (mathPow(candidate, .5)*maxWord)|0;
          k[primeCounter++] = (mathPow(candidate, 1/3)*maxWord)|0;
        }
      }
      ascii += '\x80';
      while (ascii[lengthProperty] % 64 - 56) ascii += '\x00';
      for (i = 0; i < ascii[lengthProperty]; i++) {
        j = ascii.charCodeAt(i);
        if (j >> 8) return ""; // ASCII only
        words[i >> 2] |= j << ((3 - i % 4) * 8);
      }
      words[words[lengthProperty]] = ((asciiLength * 8) / maxWord) | 0;
      words[words[lengthProperty]] = (asciiLength * 8);

      var h0 = hash[0], h1 = hash[1], h2 = hash[2], h3 = hash[3], h4 = hash[4], h5 = hash[5], h6 = hash[6], h7 = hash[7];
      for (j = 0; j < words[lengthProperty]; j += 16) {
        var w = words.slice(j, j + 16);
        var oldh0 = h0, oldh1 = h1, oldh2 = h2, oldh3 = h3, oldh4 = h4, oldh5 = h5, oldh6 = h6, oldh7 = h7;
        for (i = 0; i < 64; i++) {
          if (i >= 16) {
            var w15 = w[i - 15], w2 = w[i - 2];
            var s0 = rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3);
            var s1 = rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10);
            w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
          }
          var a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h_val = h7;
          var s0_rot = rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22);
          var maj = (a & b) ^ (a & c) ^ (b & c);
          var t2 = (s0_rot + maj) | 0;
          var s1_rot = rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25);
          var ch = (e & f) ^ ((~e) & g);
          var t1 = (h_val + s1_rot + ch + k[i] + (w[i] || 0)) | 0;
          h0 = (t1 + t2) | 0;
          h1 = a;
          h2 = b;
          h3 = c;
          h4 = (d + t1) | 0;
          h5 = e;
          h6 = f;
          h7 = g;
        }
        h0 = (h0 + oldh0) | 0;
        h1 = (h1 + oldh1) | 0;
        h2 = (h2 + oldh2) | 0;
        h3 = (h3 + oldh3) | 0;
        h4 = (h4 + oldh4) | 0;
        h5 = (h5 + oldh5) | 0;
        h6 = (h6 + oldh6) | 0;
        h7 = (h7 + oldh7) | 0;
      }
      var hash_vals = [h0, h1, h2, h3, h4, h5, h6, h7];
      for (i = 0; i < 8; i++) {
        var byte_val = hash_vals[i];
        if (byte_val < 0) byte_val += 4294967296;
        var hex = byte_val.toString(16);
        while (hex.length < 8) hex = '0' + hex;
        result += hex;
      }
      return result;
    }

    async function hashPassword(p) {
      try {
        if (window.crypto && window.crypto.subtle && typeof window.crypto.subtle.digest === 'function') {
          const enc = new TextEncoder();
          const buf = await crypto.subtle.digest('SHA-256', enc.encode(p + 'EK2024'));
          return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2,'0')).join('');
        }
      } catch (e) {
        console.warn("Native crypto.subtle.digest failed, falling back to pure JS hash:", e);
      }
      return sha256_js(p + 'EK2024');
    }

    async function verifyPassword(plain, stored) {
      if (!stored) return false;
      const hash = stored.startsWith('hash:') ? stored.slice(5) : stored;
      if (!stored.startsWith('hash:') && stored.length !== 64) {
        if (plain === stored) return true;
      }
      return (await hashPassword(plain)) === hash;
    }

    async function migratePasswordsToHash() {
      try {
        const migrated = getData('ek_passwords_migrated', false);
        if (migrated) return;

        let adminChanged = false;
        for (let acc of adminAccounts) {
          if (acc.password && !acc.password.startsWith('hash:')) {
            acc.password = 'hash:' + await hashPassword(acc.password);
            adminChanged = true;
          }
        }
        if (adminChanged) saveData('ek_admin_accounts', adminAccounts);

        let delivList = getData('ek_delivery_persons', []);
        let changed = false;
        for (let dp of delivList) {
          if (dp.password && !dp.password.startsWith('hash:')) {
            dp.password = 'hash:' + await hashPassword(dp.password);
            changed = true;
          }
        }
        if (changed) saveData('ek_delivery_persons', delivList);

        let users = getData('ek_users', []);
        let usersChanged = false;
        for (let u of users) {
          if (u.password && !u.password.startsWith('hash:')) {
            u.password = 'hash:' + await hashPassword(u.password);
            usersChanged = true;
            if (typeof db !== 'undefined' && db && u.id) {
              db.collection('ek_users').doc(u.id).update({
                password: u.password,
                updatedAt: new Date().toISOString()
              }).catch(e => console.warn('[Migration] Firestore password sync failed:', u.id, e));
            }
          }
        }
        if (usersChanged) saveData('ek_users', users);

        saveData('ek_passwords_migrated', true);
        debugLog('[Security] All passwords migrated to SHA-256 hash successfully.');
      } catch (err) {
        console.error('[Security] Passwords migration failed safely:', err);
      }
    }

    function archiveOldOrders() {
      const orders = getData('ek_orders', []);
      const cutoff = Date.now() - (90 * 24 * 60 * 60 * 1000); // 90 days

      const activeOrders = orders.filter(o => {
        const isFinal = ['delivered', 'cancelled'].includes(o.status);
        const orderTime = new Date(o.createdAt || 0).getTime();
        return !isFinal || orderTime > cutoff; // Keep recent + all non-final orders
      });

      if (activeOrders.length !== orders.length) {
        saveData('ek_orders', activeOrders);
        debugLog(`[Archive] Removed ${orders.length - activeOrders.length} old orders from local storage (retained in Firestore).`);
      }
    }

    async function fetchSettingsOnce() {
      if (typeof db === 'undefined' || !db) {
        window._isSettingsFetched = true;
        window._hasFreshSettings = true;
        checkAndUpdateFreshCloudData();
        return;
      }
      try {
        const doc = await db.collection('ek_settings').doc('global_config').get();
        if (doc.exists) {
          const cloudSettings = normalizeFirestoreData(doc.data());
          if (cloudSettings) {
            const localSettings = getData('ek_settings', DEFAULT_SETTINGS);
            const cloudTime = new Date(cloudSettings.updatedAt || 0).getTime();
            const localTime = new Date(localSettings.updatedAt || 0).getTime();
            const localIsDefault = !localSettings._isAdminModified || localTime === 0;

            if (cloudTime >= localTime || localIsDefault || (cloudSettings.slidingBanners && cloudSettings.slidingBanners.length > 0)) {
              saveData('ek_settings', cloudSettings);
              invalidateDataCache('ek_settings');
              window._isSettingsFetched = true;
              window._hasFreshSettings = true;
              checkAndUpdateFreshCloudData();
              window._hasFreshSettings = true;
              _lastBannersHash = '';
              if (typeof currentScreen !== 'undefined') {
                if (currentScreen === 'screen-home' && typeof renderSlidingBanners === 'function') renderSlidingBanners();
                else if (currentScreen === 'screen-admin' && typeof renderAdminBannerList === 'function') renderAdminBannerList();
              }
              debugLog('[Cloud Sync] Settings fetched once successfully!');
            } else if (localTime > cloudTime && localSettings._isAdminModified) {
              window._hasFreshSettings = true;
              window._isSettingsFetched = true;
              window._hasFreshSettings = true;
              checkAndUpdateFreshCloudData();
              _lastBannersHash = '';
              if (typeof currentScreen !== 'undefined' && currentScreen === 'screen-home' && typeof renderSlidingBanners === 'function') renderSlidingBanners();
              debugLog('[Cloud Sync] Local settings are newer than cloud settings. Syncing local settings to cloud...');
              db.collection('ek_settings').doc('global_config').set(cleanFirestoreData(localSettings)).catch(err => console.error("Error syncing local settings to cloud:", err));
            } else {
              window._hasFreshSettings = true;
              window._isSettingsFetched = true;
              window._hasFreshSettings = true;
              checkAndUpdateFreshCloudData();
              _lastBannersHash = '';
              if (typeof currentScreen !== 'undefined' && currentScreen === 'screen-home' && typeof renderSlidingBanners === 'function') renderSlidingBanners();
            }
          } else {
            window._hasFreshSettings = true;
            window._isSettingsFetched = true;
              window._hasFreshSettings = true;
              checkAndUpdateFreshCloudData();
            _lastBannersHash = '';
            if (typeof currentScreen !== 'undefined' && currentScreen === 'screen-home' && typeof renderSlidingBanners === 'function') renderSlidingBanners();
          }
        } else {
          window._hasFreshSettings = true;
          window._isSettingsFetched = true;
              window._hasFreshSettings = true;
              checkAndUpdateFreshCloudData();
          _lastBannersHash = '';
          if (typeof currentScreen !== 'undefined' && currentScreen === 'screen-home' && typeof renderSlidingBanners === 'function') renderSlidingBanners();
        }
      } catch (e) {
        console.error('[Cloud Sync] Settings fetch failed:', e);
        window._hasFreshSettings = true;
        window._isSettingsFetched = true;
              window._hasFreshSettings = true;
              checkAndUpdateFreshCloudData();
        _lastBannersHash = '';
        if (typeof currentScreen !== 'undefined' && currentScreen === 'screen-home' && typeof renderSlidingBanners === 'function') renderSlidingBanners();
      }
    }

    async function fetchProductsOnce() {
      if (typeof db === 'undefined' || !db) {
        debugLog('[DEBUG fetchProductsOnce] db is undefined or null');
        window._isProductsFetched = true;
        checkAndUpdateFreshCloudData();
        return;
      }
      debugLog('[DEBUG fetchProductsOnce] starting fetch from Firestore...');
      const cachedProds = getData('ek_products', []);
      const cachedCats = getData('ek_categories', []);
      isProductsLoading = !cachedProds || cachedProds.length === 0;
      isCategoriesLoading = !cachedCats || cachedCats.length === 0;
      productsLoadError = null;
      categoriesLoadError = null;
      if (typeof renderHomeScreenProducts === 'function') {
        renderHomeScreenProducts();
      }
      try {
        const [productsSnap, categoriesSnap] = await Promise.all([
          db.collection('ek_products').get(),
          db.collection('ek_categories').get()
        ]);

        const deletedProdIds = getDeletedProductIds();
        let cloudProducts = [];
        productsSnap.forEach(doc => {
          const prod = normalizeFirestoreData(doc.data());
          if (prod && prod.id && !deletedProdIds.includes(prod.id)) {
            cloudProducts.push(prod);
          }
        });

        let cloudCategories = [];
        categoriesSnap.forEach(doc => {
          const cat = normalizeFirestoreData(doc.data());
          if (cat && cat.id) {
            cloudCategories.push(cat);
          }
        });

        const isCloudInitialized = getData('ek_cloud_initialized') === true;
        if (typeof ENABLE_DEMO_SEED_DATA !== 'undefined' && ENABLE_DEMO_SEED_DATA && !isCloudInitialized) {
          if (cloudProducts.length === 0) {
            debugLog("[Cloud Sync] First time cloud setup: returned 0 products. Seeding initial demo products...");
            cloudProducts = DEMO_PRODUCTS
              .filter(p => !deletedProdIds.includes(p.id))
              .map(p => ({
                ...p,
                updatedAt: p.createdAt || new Date().toISOString()
              }));

            cloudProducts.forEach(p => {
              db.collection('ek_products').doc(p.id).set(cleanFirestoreData(p))
                .then(() => debugLog(`[Cloud Sync] Auto-seeded product ${p.id} to Firestore.`))
                .catch(e => console.warn(`[Cloud Sync] Failed to seed product ${p.id} to Firestore:`, e));
            });
          }
          saveData('ek_cloud_initialized', true);
        }

          if (cloudCategories.length === 0) {
            debugLog("[Cloud Sync] Cloud returned 0 categories. Seeding default categories locally and pushing to Firestore...");
            cloudCategories = DEFAULT_CATEGORIES.map(c => ({
              ...c,
              isAvailable: true,
              order: c.order !== undefined ? c.order : 0
            }));

            cloudCategories.forEach(c => {
              db.collection('ek_categories').doc(c.id).set(cleanFirestoreData(c))
                .then(() => debugLog(`[Cloud Sync] Auto-seeded category ${c.id} to Firestore.`))
                .catch(e => console.warn(`[Cloud Sync] Failed to seed category ${c.id} to Firestore:`, e));
            });
          } else {
            DEFAULT_CATEGORIES.forEach(c => {
              if (!cloudCategories.some(cc => cc.id === c.id)) {
                debugLog(`[Cloud Sync] Default category ${c.id} missing from cloud. Injecting locally for robust fallback.`);
                cloudCategories.push(c);
              }
            });
          }

        const jsonProducts = JSON.stringify(cloudProducts);
        localStorage.setItem('ek_products', jsonProducts);
        if (typeof AndroidStorage !== 'undefined') {
          AndroidStorage.saveData('ek_products', jsonProducts);
        }
        invalidateDataCache('ek_products');

        cloudCategories.sort((a, b) => {
          const orderA = Number(a.order !== undefined && a.order !== null ? a.order : 999);
          const orderB = Number(b.order !== undefined && b.order !== null ? b.order : 999);
          if (orderA !== orderB) return orderA - orderB;
          return String(a.id || "").localeCompare(String(b.id || ""));
        });
        const jsonCategories = JSON.stringify(cloudCategories);
        localStorage.setItem('ek_categories', jsonCategories);
        if (typeof AndroidStorage !== 'undefined') {
          AndroidStorage.saveData('ek_categories', jsonCategories);
        }
        invalidateDataCache('ek_categories');

        debugLog(`[Cloud Sync] Fetched once successfully: ${cloudProducts.length} products, ${cloudCategories.length} categories.`);
      } catch (err) {
        console.error(`[Cloud Sync] ek_products / ek_categories query failed:`, err);
        productsLoadError = err.message || String(err);
        categoriesLoadError = err.message || String(err);
        window._isProductsFetched = true;
        checkAndUpdateFreshCloudData();
      } finally {
        isProductsLoading = false;
        isCategoriesLoading = false;
        window._isProductsFetched = true;
        checkAndUpdateFreshCloudData();
        if (typeof renderHomeScreenProducts === 'function') {
          renderHomeScreenProducts();
        }
        if (typeof renderCategoryPills === 'function') {
          renderCategoryPills();
        }
      }
    }

