          { id: 'zone_comp1', nameEn: 'Edappadi Mini Ward (Town Core)', nameTa: 'எடப்பாடி டவுன் வார்டு', maxKm: 2.5, charge: 15 },
          { id: 'zone_comp2', nameEn: 'Outer bypass road / Highways', nameTa: 'பைபாஸ் டோல்கேட் / ஹைவேஸ்', maxKm: 5.0, charge: 35 },
          { id: 'zone_comp3', nameEn: 'Peripheral District Village Bounds', nameTa: 'மாவட்ட எல்லை பகுதி கிராமங்கள்', maxKm: 12.0, charge: 75 }
