          { id: 'zone_std2', nameEn: 'Suburbs Middle Ring (3-7 KM)', nameTa: 'புறநகர் பகுதி (3-7 கி.மீ)', maxKm: 7.0, charge: 45 },
          { id: 'zone_std3', nameEn: 'Extended Salem Outskirts (7-15 KM)', nameTa: 'சேலம் புறநகர் எல்லை (7-15 கி.மீ)', maxKm: 15.0, charge: 90 }
