          { id: 'zone_metro2', nameEn: 'Outer Metropolitan bypass (4-8 KM)', nameTa: 'வெளிவட்டார பைபாஸ் (4-8 கி.மீ)', maxKm: 8.0, charge: 60 },
          { id: 'zone_metro3', nameEn: 'Extended Urban Bound (8-20 KM)', nameTa: 'விரிவாக்கப்பட்ட பெருநகரம் (8-20 கி.மீ)', maxKm: 20.0, charge: 150 }
