    function toggleDeliveryMode(mode) {
      const elDynDel = document.getElementById('setting-dynamic-delivery');
      if (elDynDel) {
        elDynDel.checked = (mode === 'dynamic');
      }
      updateDeliveryModeUI();
      saveAdminSettings();
    }

    function updateDeliveryModeUI() {
      const elDynDel = document.getElementById('setting-dynamic-delivery');
      if (!elDynDel) return;

      const mode = elDynDel.checked ? 'dynamic' : 'flat';
      const btnFlat = document.getElementById('btn-delivery-mode-flat');
      const btnDynamic = document.getElementById('btn-delivery-mode-dynamic');

      const groupFlat = document.getElementById('group-delivery-flat-config');
      const groupDynamic = document.getElementById('group-delivery-dynamic-config');

      if (mode === 'flat') {
        if (btnFlat) {
          btnFlat.style.background = 'var(--accent-orange)';
          btnFlat.style.color = '#000';
        }
        if (btnDynamic) {
          btnDynamic.style.background = 'transparent';
          btnDynamic.style.color = 'var(--text-secondary)';
        }
        if (groupFlat) groupFlat.style.display = 'block';
        if (groupDynamic) groupDynamic.style.display = 'none';
      } else {
        if (btnFlat) {
          btnFlat.style.background = 'transparent';
          btnFlat.style.color = 'var(--text-secondary)';
        }
        if (btnDynamic) {
          btnDynamic.style.background = 'var(--accent-orange)';
          btnDynamic.style.color = '#000';
        }
        if (groupFlat) groupFlat.style.display = 'none';
        if (groupDynamic) groupDynamic.style.display = 'block';
        setTimeout(() => {
          initAdminZonesMap();
        }, 120);
      }
    }

    function presetDeliveryFee(val) {
      const input = document.getElementById('setting-delivery-charge');
      if (input) {
        input.value = val;
        saveAdminSettings();
        showToast(`Standard delivery fee updated to ₹${val} instantly!`, "success");
      }
    }

    function changeZoneFee(zoneId, diff) {
      const settings = getData('ek_settings', DEFAULT_SETTINGS);
      if (!settings.deliveryZones) {
        settings.deliveryZones = JSON.parse(JSON.stringify(DEFAULT_SETTINGS.deliveryZones || []));
      }
      const zone = settings.deliveryZones.find(z => z.id === zoneId);
      if (zone) {
        zone.charge = Math.max(0, (parseInt(zone.charge) || 0) + diff);
        saveData('ek_settings', settings);

        if (typeof db !== 'undefined' && db && db.collection) {
          db.collection('ek_settings').doc('global_config').set(cleanFirestoreData(settings))
            .then(() => debugLog("[Cloud Live Sync] Modified zone charge."))
            .catch(err => console.error("Cloud sync zone modification failed:", err));
        }

        renderAdminDeliveryZones();
        showToast(`Zone fee adjusted correctly!`, "success");
      }
    }

    function handleAddDeliveryZone(e) {
      if (e) e.preventDefault();
      const nameInp = document.getElementById('new-zone-name');
      const maxInp = document.getElementById('new-zone-max');
      const chargeInp = document.getElementById('new-zone-charge');

      if (!nameInp || !maxInp || !chargeInp) return;

      const name = nameInp.value.trim();
      const maxKm = parseFloat(maxInp.value);
      const charge = parseInt(chargeInp.value);

      if (!name) {
        showToast("Please enter a Zone Name / மண்டல பெயர்!", "error");
        return;
      }
      if (isNaN(maxKm) || maxKm <= 0) {
        showToast("Please enter a valid max kilometer / சரியான தொலைவு!", "error");
        return;
      }
      if (isNaN(charge) || charge < 0) {
        showToast("Please enter a valid price / சரியான கட்டணம்!", "error");
        return;
      }

      const settings = getData('ek_settings', DEFAULT_SETTINGS);
      if (!settings.deliveryZones) {
        settings.deliveryZones = JSON.parse(JSON.stringify(DEFAULT_SETTINGS.deliveryZones || []));
      }

      if (settings.deliveryZones.some(z => z.maxKm === maxKm)) {
        showToast("A zone with this max boundary distance already exists!", "error");
        return;
      }

      const newZone = {
        id: 'zone_' + Math.floor(1000 + Math.random() * 9000),
        nameEn: name,
        nameTa: name,
        maxKm: maxKm,
        charge: charge
      };

      settings.deliveryZones.push(newZone);
      saveData('ek_settings', settings);

      nameInp.value = '';
      maxInp.value = '';
      chargeInp.value = '';

      renderAdminDeliveryZones();
      showToast("Zone added successfully! தூர மண்டலம் சேர்க்கப்பட்டது. 🎉", "success");
    }

    function handleDeleteDeliveryZone(zoneId) {
      const settings = getData('ek_settings', DEFAULT_SETTINGS);
      if (!settings.deliveryZones) {
        settings.deliveryZones = JSON.parse(JSON.stringify(DEFAULT_SETTINGS.deliveryZones || []));
      }

      settings.deliveryZones = settings.deliveryZones.filter(z => z.id !== zoneId);
      saveData('ek_settings', settings);

      renderAdminDeliveryZones();
      showToast("Zone deleted / மண்டலம் நீக்கப்பட்டது.", "success");
    }

    function toggleSmsFormFields() {
      const provEl = document.getElementById('setting-sms-provider');
      if (!provEl) return;
      const provider = provEl.value;

      const elementsMap = {
        'sms-fields-fast2sms': provider === 'fast2sms',
        'sms-fields-twilio': provider === 'twilio',
        'sms-fields-custom': provider === 'custom'
      };

      Object.keys(elementsMap).forEach(id => {
        const el = document.getElementById(id);
        if (el) {
          el.style.display = elementsMap[id] ? 'block' : 'none';
        }
      });
    }

    async function loadAdminSmsSettingsUI(settings) {
      const provEl = document.getElementById('setting-sms-provider');
      if (provEl) provEl.value = settings.smsProvider || 'simulator';

      const keyEl = document.getElementById('setting-fast2sms-key');
      if (keyEl) { keyEl.value = ''; keyEl.placeholder = 'Enter Fast2SMS API Key'; }

      const twSidEl = document.getElementById('setting-twilio-sid');
      if (twSidEl) { twSidEl.value = ''; twSidEl.placeholder = 'ACxxxxxxxxxxxxxxxxxxxxxxxx'; }

      const twTokEl = document.getElementById('setting-twilio-token');
      if (twTokEl) { twTokEl.value = ''; twTokEl.placeholder = 'Twilio Secret Token'; }

      const twFromEl = document.getElementById('setting-twilio-from');
      if (twFromEl) { twFromEl.value = ''; twFromEl.placeholder = '+1xxxxxxxxxx'; }

      const custUrlEl = document.getElementById('setting-sms-custom-url');
      if (custUrlEl) { custUrlEl.value = ''; custUrlEl.placeholder = 'https://api.sms-provider.com/...'; }

      const getStatus = getCloudFunction('getSmsGatewayStatus');
      if (getStatus) {
        try {
          const res = await getStatus();
          if (res && res.data) {
            const data = res.data;
            if (data.provider && provEl) provEl.value = data.provider;

            if (keyEl && data.hasApiKey) keyEl.placeholder = 'Fast2SMS API Key: Configured';
            if (twSidEl && data.hasTwilioSid) twSidEl.placeholder = 'Twilio SID: Configured';
            if (twTokEl && data.hasTwilioToken) twTokEl.placeholder = 'Twilio Token: Configured';
            if (twFromEl && data.hasTwilioFrom) twFromEl.placeholder = 'Twilio From Number: Configured';
            if (custUrlEl && data.hasCustomUrl) custUrlEl.placeholder = 'Custom API URL: Configured';
          }
        } catch (err) {
          console.warn("Could not load SMS gateway status from cloud function:", err);
        }
      }

      toggleSmsFormFields();
    }

    function testCurrentSmsConfig() {
      const activeUser = getSessionUser();
      let phone = "919042681532"; // Standard test prefix
      if (activeUser && activeUser.phone) {
        phone = activeUser.phone;
      }

      const testCode = Math.floor(100000 + Math.random() * 900000);
      showToast("Triggering test secure OTP message...", "info");
      sendRealSmsOTP(phone, testCode).then(success => {
        if (success) {
          showToast(`Test OTP (${testCode}) processed correctly. Please check your phone! 📱`, "success");
        }
      });
    }

    async function sendRealSmsOTP(phoneNumber, otpCode) {
      const settings = getData('ek_settings', DEFAULT_SETTINGS);
      const provider = settings.smsProvider || 'simulator';

      const messageText = `Edappadi Kadai security verification OTP is: ${otpCode}. Valid for 5 mins. Do not share.`;

      let cleanPhone = String(phoneNumber).replace(/\s+/g, '');
      if (cleanPhone.length === 10 && !cleanPhone.startsWith('+')) {
        cleanPhone = '91' + cleanPhone; // Fallback to Indian Mobile prefix (91)
      }

      debugLog(`[SMS Gateway Dispatch] Channel: ${provider} | Target: ${cleanPhone}`);

      if (provider === 'simulator') {
        const msg = currentLang === 'ta'
          ? `[மாதிரி] உங்கள் பாதுகாப்பு குறியீடு OTP: ${otpCode} (தொலைபேசி: ${cleanPhone})`
          : `[SIMULATOR] Your security OTP is: ${otpCode} (for phone: ${cleanPhone})`;
        showToast(msg, "success");
        return true;
      }

      try {
        const sendOtpSmsFn = getCloudFunction('sendOtpSms');
        if (!sendOtpSmsFn) {
          showToast(
            currentLang === 'ta'
              ? "சர்வர் சேவை இன்னும் செயல்படுத்தப்படவில்லை. தயவுசெய்து பின்னர் முயற்சிக்கவும்."
              : "Server service is not deployed yet. Please try again later.",
            "error"
          );
          return false;
        }
        const result = await sendOtpSmsFn({ phoneNumber: cleanPhone, otpCode: otpCode });
        if (result && result.data && result.data.success) {
          showToast(`Secure SMS OTP dispatched successfully! 📲 (${provider.toUpperCase()})`, "success");
          return true;
        } else {
          showToast(`Secure SMS dispatch failed: ${result?.data?.message || 'Unknown server error'}`, "error");
          return false;
        }
      } catch (err) {
        console.error("[Cloud Function SMS Dispatch Error]", err);
        const isNotDeployed = err && (err.code === 'not-found' || err.message?.includes('not-found') || err.code === 'unimplemented');
        const msg = isNotDeployed
          ? (currentLang === 'ta' ? "சர்வர் சேவை இன்னும் செயல்படுத்தப்படவில்லை. தயவுசெய்து பின்னர் முயற்சிக்கவும்." : "Server service is not deployed yet. Please try again later.")
          : `Secure SMS transmission failed: ${err.message || err.toString()}`;
        showToast(msg, "error");
        return false;
      }
    }

    let cachedAdminBannerBase64 = null;
    let currentCarouselIndex = 0;
