    async function addNewSlidingBanner() {
      const settings = getData('ek_settings', DEFAULT_SETTINGS);
      if (!settings.slidingBanners) {
        settings.slidingBanners = [
          { id: 'b_1', image: 'https://images.unsplash.com/photo-1603360946369-dc9bb6258143?w=800', titleTa: "நாட்டு ஆட்டுக்கறி பிரஷ்ஷாக!", titleEn: "Premium Fresh Mutton Cuts", subTa: "இடப்பாடி நகரத்தில் உங்களின் இல்லத்திற்கே நேரடியாக!", subEn: "Direct organic local meat delivered to your home." },
          { id: 'b_2', image: 'https://images.unsplash.com/photo-1587593810167-a84920ea0781?w=800', titleTa: "தரமான நாட்டுக்கோழி!", titleEn: "Farm Fresh Chicken Varieties", subTa: "சுத்தமான முறையில் கட் செய்து வழங்கப்படும்!", subEn: "Cleanly cut & prepared perfectly for your tasty health." },
          { id: 'b_3', image: 'https://images.unsplash.com/photo-1540420773420-3366772f4999?w=800', titleTa: "இயற்கை காய்கறிகள் & கீரைகள்!", titleEn: "100% Organic Village Greens", subTa: "பிரஷ்ஷான கிராமத்து இயற்கை விவசாய விளைச்சல்!", subEn: "Freshly harvested organic local farm yields." }
        ];
      }

      const isEditing = (typeof window.editingBannerId !== 'undefined' && window.editingBannerId !== null);

      if (!isEditing && settings.slidingBanners.length >= 10) {
        showToast("Maximum of 10 slider banners reached! Please delete older slides first.", "error");
        return;
      }

      const fileUrl = cachedAdminBannerBase64;
      const directUrl = document.getElementById('admin-banner-url-input').value.trim();
      const titleTa = document.getElementById('admin-banner-title-ta').value.trim();
      const titleEn = document.getElementById('admin-banner-title-en').value.trim();
      const subTa = document.getElementById('admin-banner-sub-ta').value.trim();
      const subEn = document.getElementById('admin-banner-sub-en').value.trim();

      let activeImg = directUrl;

      if (fileUrl) {
        if (typeof firebase !== 'undefined' && firebase.storage) {
          try {
            showToast('விளம்பரப் படம் பதிவேற்றப்படுகிறது... ⏳', 'info');
            const storage = firebase.storage();

            try {
              if (typeof storage.setMaxUploadRetryTime === 'function') {
                storage.setMaxUploadRetryTime(10000); // 10s max upload retry
              } else {
                storage.maxUploadRetryTime = 10000;
              }
              if (typeof storage.setMaxOperationRetryTime === 'function') {
                storage.setMaxOperationRetryTime(10000); // 10s max operation retry
              } else {
                storage.maxOperationRetryTime = 10000;
              }
            } catch (confErr) {
              console.warn("[Banner Storage Config] Failed to set retry limits:", confErr);
            }

            const storageRef = storage.ref();
            const slideId = isEditing ? window.editingBannerId : 'b_' + Date.now();
            const imageRef = storageRef.child(`banner_images/${slideId}.jpg`);

            const uploadTaskPromise = new Promise((resolve, reject) => {
              const uploadTask = imageRef.putString(fileUrl, 'data_url');
              let progressStarted = false;

              const progressTimer = setTimeout(() => {
                if (!progressStarted) {
                  console.warn("[Banner Upload] Stuck at 0% for 3 seconds. Canceling and falling back...");
                  try { uploadTask.cancel(); } catch (e) {}
                  reject(new Error("UPLOAD_STUCK_AT_0"));
                }
              }, 3000);

              uploadTask.on('state_changed',
                (snapshot) => {
                  const progress = Math.round((snapshot.bytesTransferred / snapshot.totalBytes) * 100);
                  if (progress > 0) {
                    progressStarted = true;
                    clearTimeout(progressTimer);
                  }
                },
                (error) => {
                  clearTimeout(progressTimer);
                  reject(error);
                },
                () => {
                  clearTimeout(progressTimer);
                  imageRef.getDownloadURL().then(url => resolve(ensureCacheBustingUrl(url))).catch(reject);
                }
              );
            });

            const maxTimeout = setTimeout(() => {
              console.warn("[Banner Upload] Max timeout reached. Falling back.");
            }, 8000);

            try {
              activeImg = await uploadTaskPromise;
              clearTimeout(maxTimeout);
              debugLog('[Banner Upload] Banner image uploaded to Storage successfully:', activeImg);
            } catch (err) {
              clearTimeout(maxTimeout);
              console.error('[Banner Upload] Failed, falling back to base64:', err);
              showToast("விளம்பரப் படம் ஆஃப்லைன் முறையில் தயார் செய்யப்பட்டது! / Banner processed & saved offline!", "info");
              activeImg = fileUrl; // Fallback
            }
          } catch (uploadErr) {
            console.error('[Banner Storage Error] Fallback active:', uploadErr);
            activeImg = fileUrl;
          }
        } else {
          activeImg = fileUrl;
        }
      }

      if (!activeImg && isEditing) {
        const existingSlide = settings.slidingBanners.find(b => b.id === window.editingBannerId);
        if (existingSlide) {
          activeImg = existingSlide.image;
        }
      }

      if (!activeImg) {
        showToast("Please choose an image file or paste an image URL!", "error");
        return;
      }

      if (isEditing) {
        const idx = settings.slidingBanners.findIndex(b => b.id === window.editingBannerId);
        if (idx !== -1) {
          const oldSlide = settings.slidingBanners[idx];
          settings.slidingBanners[idx] = {
            id: window.editingBannerId,
            image: activeImg,
            titleTa: titleTa || "",
            titleEn: titleEn || "",
            subTa: subTa || "",
            subEn: subEn || "",
            displayOrder: oldSlide.displayOrder !== undefined ? oldSlide.displayOrder : idx,
            isActive: oldSlide.isActive !== undefined ? oldSlide.isActive : true,
            createdAt: oldSlide.createdAt || new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            uploadedBy: oldSlide.uploadedBy || (getAdminSession() ? (getAdminSession().name || getAdminSession().phone) : "Admin")
          };
          showToast("Sliding banner updated successfully! ✓", "success");
          showAdminSuccessModal(
            "🎉 வெற்றிகரமாக பேனர் மாற்றப்பட்டது!",
            `விளம்பரப் பேனர் வெற்றிகரமாக மாற்றப்பட்டு உங்களது கடையின் முகப்புத் திரையில் சேமிக்கப்பட்டது.<br><br><span style="font-size:11.5px;color:var(--text-muted);">The sliding banner has been successfully modified!</span>`
          );
        } else {
          showToast("Error updating banner.", "error");
          return;
        }
      } else {
        const adminSession = getAdminSession();
        const uploadedBy = adminSession ? (adminSession.name || adminSession.phone) : "Admin";
        const newSlide = {
          id: 'b_' + Date.now(),
          image: activeImg,
          titleTa: titleTa || "",
          titleEn: titleEn || "",
          subTa: subTa || "",
          subEn: subEn || "",
          displayOrder: settings.slidingBanners.length,
          isActive: true,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          uploadedBy: uploadedBy
        };
        settings.slidingBanners.push(newSlide);
        showToast("New sliding banner added successfully! ✓", "success");
        showAdminSuccessModal(
          "🎉 வெற்றிகரமாக பேனர் இணைக்கப்பட்டது!",
          `புதிய விளம்பரப் பேனர் வெற்றிகரமாக இணைக்கப்பட்டு உங்களது கடையின் முகப்புத் திரையில் சேமிக்கப்பட்டது.<br><br><span style="font-size:11.5px;color:var(--text-muted);">The sliding banner has been successfully added to your home screen carousel!</span>`
        );
      }

      window.editingBannerId = null;
      cachedAdminBannerBase64 = null;
      document.getElementById('admin-banner-file-input').value = "";
      document.getElementById('admin-banner-url-input').value = "";
      document.getElementById('admin-banner-title-ta').value = "";
      document.getElementById('admin-banner-title-en').value = "";
      document.getElementById('admin-banner-sub-ta').value = "";
      document.getElementById('admin-banner-sub-en').value = "";

      const previewContainer = document.getElementById('admin-banner-preview-container');
      if (previewContainer) previewContainer.style.display = 'none';

      const formTitle = document.getElementById('admin-banner-form-title');
      if (formTitle) {
        formTitle.innerHTML = `⚡ புதிய பேனர் சேர்க்க / Add New Slide`;
      }
      const submitBtn = document.getElementById('admin-banner-submit-btn');
      if (submitBtn) {
        submitBtn.innerHTML = `<span>➕ ADD TO CAROUSEL</span>`;
      }
      const cancelBtn = document.getElementById('admin-banner-cancel-btn');
      if (cancelBtn) {
        cancelBtn.style.display = 'none';
      }

      settings.updatedAt = new Date().toISOString();
      _lastBannersHash = '';
      invalidateDataCache('ek_settings');
      saveData('ek_settings', settings);

      renderAdminBannerList();
      renderSlidingBanners();
      cloudSyncSaveSettings(settings);
    }

    function deleteSlidingBanner(id) {
      const settings = getData('ek_settings', DEFAULT_SETTINGS);
      let banners = settings.slidingBanners;
      if (!banners) {
        banners = DEFAULT_SETTINGS.slidingBanners || [];
      }

      if (banners.length <= 1) {
        showToast("You must keep at least 1 active slider banner!", "error");
        return;
      }

      settings.slidingBanners = banners.filter(b => b.id !== id);
      settings.updatedAt = new Date().toISOString();
      _lastBannersHash = '';
      invalidateDataCache('ek_settings');
      saveData('ek_settings', settings);

      renderAdminBannerList();

      if (currentCarouselIndex >= settings.slidingBanners.length) {
        currentCarouselIndex = 0;
      }
      renderSlidingBanners();
      cloudSyncSaveSettings(settings);
      showToast("Sliding banner deleted successfully!", "info");
      showAdminSuccessModal(
        currentLang === 'ta' ? "🗑️ பேனர் நீக்கப்பட்டது!" : "🗑️ Banner Deleted!",
        currentLang === 'ta' ? `விளம்பரப் பேனர் வெற்றிகரமாக நீக்கப்பட்டது.` : `The sliding banner has been successfully deleted.`
      );
    }

