    function cloudSyncSaveSettings(settings) {
      if (!settings) return;
      if (!settings.updatedAt) settings.updatedAt = new Date().toISOString();

      const cleanSettings = typeof cleanFirestoreData === 'function' ? cleanFirestoreData(settings) : { ...settings };
      delete cleanSettings.smsApiKey;
      delete cleanSettings.smsTwilioSid;
      delete cleanSettings.smsTwilioToken;
      delete cleanSettings.smsTwilioFrom;
      delete cleanSettings.smsCustomUrl;

      invalidateDataCache('ek_settings');
      saveData('ek_settings', cleanSettings);

      if (typeof db !== 'undefined' && db && db.collection) {
        db.collection('ek_settings').doc('global_config').set(cleanFirestoreData(cleanSettings))
          .then(() => debugLog("[Cloud Settings] Public settings uploaded to Cloud!"))
          .catch(err => {
            console.error("Cloud upload error for settings: ", err);
          });
      }
    }

    window._hasFreshSettings = false;
    window._hasFreshCloudData = false;
window._isSettingsFetched = false;
window._isProductsFetched = false;

function checkAndUpdateFreshCloudData() {
  if (window._isSettingsFetched && window._isProductsFetched) {
    window._hasFreshCloudData = true;
    if (typeof _lastBannersHash !== "undefined") _lastBannersHash = "";
    if (typeof _lastProductsHash !== "undefined") _lastProductsHash = "";
    if (typeof _lastSpecialsHash !== "undefined") _lastSpecialsHash = "";
    if (typeof _lastCategoryPillsHash !== "undefined") _lastCategoryPillsHash = "";
    if (typeof currentScreen !== "undefined" && currentScreen === "screen-home") {
      if (typeof renderHomeScreen === "function") {
        renderHomeScreen(true);
      } else {
        if (typeof renderSlidingBanners === "function") renderSlidingBanners();
        if (typeof renderCategoryPills === "function") renderCategoryPills();
        if (typeof renderHomeScreenProducts === "function") renderHomeScreenProducts(true);
      }
    }
  }
}

    let _lastBannersHash = '';
    function renderSlidingBanners() {
      const container = document.getElementById('home-sliding-carousel');
      const dotsContainer = document.getElementById('carousel-dots-container');
      if (!container) return;

      if (!window._hasFreshCloudData) {
        container.innerHTML = `
          <div class="carousel-slide" style="flex: 0 0 100%; min-width: 100%; height: 135px; position: relative; overflow: hidden; background: linear-gradient(90deg, rgba(255,255,255,0.03) 25%, rgba(255,255,255,0.08) 50%, rgba(255,255,255,0.03) 75%); background-size: 200% 100%; border-radius: 14px; display: flex; align-items: center; justify-content: center;">
            <div style="text-align: center; color: var(--text-secondary); font-size: 11px;">
              <div style="margin: 0 auto 6px auto; width: 18px; height: 18px; border: 2px solid rgba(255,255,255,0.15); border-top-color: var(--accent-orange); border-radius: 50%; animation: spin 0.8s linear infinite;"></div>
              <span>${currentLang === 'ta' ? 'விளம்பரங்கள் ஏற்றப்படுகின்றன...' : 'Loading offers...'}</span>
            </div>
          </div>
        `;
        if (dotsContainer) dotsContainer.innerHTML = '';
        return;
      }

      const settings = getSettings();
      let banners = settings.slidingBanners || [];
      debugLog('[Home Debug] Sliding banners count:', banners.length);
      if (banners.length === 0) {
        banners = [
          { id: 'b_1', image: 'https://images.unsplash.com/photo-1603360946369-dc9bb6258143?w=800', titleTa: "நாட்டு ஆட்டுக்கறி பிரஷ்ஷாக!", titleEn: "Premium Fresh Mutton Cuts", subTa: "இடப்பாடி நகரத்தில் உங்களின் இல்லத்திற்கே நேரடியாக!", subEn: "Direct organic local meat delivered to your home." },
          { id: 'b_2', image: 'https://images.unsplash.com/photo-1587593810167-a84920ea0781?w=800', titleTa: "தரமான நாட்டுக்கோழி!", titleEn: "Farm Fresh Chicken Varieties", subTa: "சுத்தமான முறையில் கட் செய்து வழங்கப்படும்!", subEn: "Cleanly cut & prepared perfectly for your tasty health." },
          { id: 'b_3', image: 'https://images.unsplash.com/photo-1540420773420-3366772f4999?w=800', titleTa: "இயற்கை காய்கறிகள் & கீரைகள்!", titleEn: "100% Organic Village Greens", subTa: "பிரஷ்ஷான கிராமத்து இயற்கை விவசாய விளைச்சல்!", subEn: "Freshly harvested organic local farm yields." }
        ];
      }

      const bannersHash = currentLang + '::' + banners.map(b => {
        if (!b) return '';
        const imgStr = b.image ? String(b.image) : '';
        const imgSig = imgStr.length + '_' + imgStr.substring(0, 20) + '_' + imgStr.slice(-20);
        return `${b.id}:${imgSig}:${b.titleEn || ''}:${b.titleTa || ''}:${b.updatedAt || ''}`;
      }).join('|');
      if (bannersHash === _lastBannersHash && container.querySelectorAll('.carousel-slide').length > 0) {
        return; // Fast skip: Carousel configuration did not change
      }
      _lastBannersHash = bannersHash;

      let slidesHtml = '';
      let dotsHtml = '';

      banners.forEach((b, idx) => {
        const title = currentLang === 'ta' ? (b.titleTa || b.titleEn) : (b.titleEn || b.titleTa);
        const sub = currentLang === 'ta' ? (b.subTa || b.subEn) : (b.subEn || b.subTa);

        slidesHtml += `
          <div class="carousel-slide" style="flex: 0 0 100%; min-width: 100%; height: 135px; position: relative; overflow: hidden; background-size: cover; background-position: center; background-image: url('${getImageUrlWithCacheBuster(b.image, b.updatedAt)}'); border-radius: 14px;">
            <div style="position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,0) 20%, rgba(0,0,0,0.7) 100%); display: flex; flex-direction: column; justify-content: flex-end; padding: 12px 14px; box-sizing: border-box;">
              <span class="badge" style="align-self: flex-start; background: rgba(245, 158, 11, 0.55); border: 1px solid rgba(255,255,255,0.25); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); color: #fff; font-size: 8px; margin-bottom: 4px; padding: 2px 7px; border-radius: 6px; text-transform: uppercase; font-weight: 800;">PREMIUM</span>
              <h3 style="margin: 0; font-size: 14.5px; color: #fff; font-weight: 800; text-shadow: 0 2px 4px rgba(0,0,0,0.9); line-height: 1.2;">${title}</h3>
              <p style="margin: 2px 0 0 0; font-size: 10.5px; color: rgba(255,255,255,0.92); text-shadow: 0 1.5px 3px rgba(0,0,0,0.9); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${sub}</p>
            </div>
          </div>
        `;

        dotsHtml += `
          <span class="carousel-dot" onclick="jumpToCarouselSlide(${idx})" style="width: 7px; height: 7px; border-radius: 50%; background: ${idx === currentCarouselIndex ? 'var(--accent-orange)' : 'rgba(255,255,255,0.3)'}; transition: all 0.3s ease; cursor: pointer;"></span>
        `;
      });

      container.innerHTML = slidesHtml;
      if (dotsContainer) {
        dotsContainer.innerHTML = dotsHtml;
      }

      updateCarouselPosition();
      startCarouselAutoSlide();
    }

    function updateCarouselPosition() {
      const container = document.getElementById('home-sliding-carousel');
      if (!container) return;

      const offset = currentCarouselIndex * 100;
      container.style.transform = `translateX(-${offset}%)`;

      const dots = document.querySelectorAll('.carousel-dot');
      dots.forEach((dot, idx) => {
        dot.style.background = idx === currentCarouselIndex ? 'var(--accent-orange)' : 'rgba(255,255,255,0.3)';
        dot.style.width = idx === currentCarouselIndex ? '16px' : '7px';
        dot.style.borderRadius = idx === currentCarouselIndex ? '4px' : '50%';
      });
    }

    function slideCarouselNext() {
      const settings = getSettings();
      let banners = settings.slidingBanners || [];
      if (banners.length === 0) banners = [{}, {}, {}];

      currentCarouselIndex = (currentCarouselIndex + 1) % banners.length;
      updateCarouselPosition();
      startCarouselAutoSlide();
    }

    function slideCarouselPrev() {
      const settings = getSettings();
      let banners = settings.slidingBanners || [];
      if (banners.length === 0) banners = [{}, {}, {}];

      currentCarouselIndex = (currentCarouselIndex - 1 + banners.length) % banners.length;
      updateCarouselPosition();
      startCarouselAutoSlide();
    }

    function jumpToCarouselSlide(idx) {
      currentCarouselIndex = idx;
      updateCarouselPosition();
      startCarouselAutoSlide();
    }

    function startCarouselAutoSlide() {
      if (carouselTimer) clearInterval(carouselTimer);
      carouselTimer = setInterval(() => {
        slideCarouselNext();
      }, 5000);
    }

    function makeDebounced(fn, delay = 250) {
      let timer = null;
      return function(...args) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
          fn.apply(this, args);
        }, delay);
      };
    }

    window.debouncedSearchCustomers = makeDebounced(() => { renderAdminCustomers(); }, 250);
    window.debouncedSearchProducts = makeDebounced(() => { renderAdminProducts(); }, 250);
    window.debouncedSearchAdminOrders = makeDebounced(() => { renderAdminOrders(); }, 250);
    window.debouncedSearchTracker = makeDebounced(() => { renderTrackerScreen(); }, 250);
    window.debouncedSearchReviews = makeDebounced(() => { renderAdminReviews(); }, 250);

    function clearHomeSearchInput() {
      const inp = document.getElementById('home-product-search');
      if (inp) {
        inp.value = '';
        onHomeSearchInput();
      }
    }

    function showTypedConfirm(title, message, requiredText, onConfirm, onCancel) {
      let modal = document.getElementById('typed-confirm-modal');
      if (!modal) {
        modal = document.createElement('div');
        modal.id = 'typed-confirm-modal';
        modal.className = 'modal-backdrop';
        modal.style.zIndex = '99999';
        modal.style.justifyContent = 'center';
        modal.style.alignItems = 'center';
        modal.style.padding = '20px';
        modal.innerHTML = `
          <div class="bottom-sheet" style="width: 100%; max-width:380px; border-radius:24px; border:1.5px solid var(--accent-orange); background:#121212; padding:24px; box-shadow:0 12px 35px rgba(0,0,0,0.85); text-align:center; transform:scale(0.85); transition:all 0.22s cubic-bezier(0.18, 0.89, 0.32, 1.28); margin:auto; display:flex; flex-direction:column; align-items:center;">
            <div style="font-size:42px; margin-bottom:14px; filter: drop-shadow(0 4px 10px rgba(0,0,0,0.35));">🧹</div>
            <h3 style="color:#ffffff; font-size:16px; margin-bottom:8px; font-weight:800; font-family:'Poppins', 'Hind Madurai', sans-serif;" id="typed-modal-title">Confirm Action</h3>
            <p style="color:var(--text-secondary); font-size:12.5px; margin-bottom:16px; line-height:1.6; word-break:break-word; max-width:100%; font-family:'Poppins', 'Hind Madurai', sans-serif;" id="typed-modal-message"></p>

            <div style="width: 100%; margin-bottom: 20px;">
              <p style="font-size: 11px; color: var(--accent-orange); font-weight: bold; margin-bottom: 8px;" id="typed-modal-instruction"></p>
              <input type="text" id="typed-modal-input" class="form-control" style="width: 100%; text-align: center; border: 1.5px solid rgba(255,255,255,0.15); background: #000; color: #fff; padding: 10px; border-radius: 10px; font-weight: bold; text-transform: uppercase;" placeholder="" autocomplete="off">
            </div>

            <div style="display:flex; gap:12px; justify-content:center; width:100%;">
              <button class="btn btn-secondary" style="flex:1; padding:10px 14px; font-size:12px; font-weight:bold; border-radius:14px; height:42px; background:#1c1c1e; color:#aeaea2; border:1px solid #2c2c2e;" id="typed-modal-cancel-btn">CLOSE</button>
              <button class="btn" style="flex:1; padding:10px 14px; font-size:12px; font-weight:800; border-radius:14px; height:42px; background:var(--accent-orange); color:#ffffff; border:1.5px solid var(--accent-orange); box-shadow:0 4px 12px rgba(245,158,11,0.25);" id="typed-modal-ok-btn">DELETE</button>
            </div>
          </div>
        `;
        document.body.appendChild(modal);
      }

      const titleEl = document.getElementById('typed-modal-title');
      const msgEl = document.getElementById('typed-modal-message');
      const instructionEl = document.getElementById('typed-modal-instruction');
      const inputEl = document.getElementById('typed-modal-input');
      const cancelBtn = document.getElementById('typed-modal-cancel-btn');
      const okBtn = document.getElementById('typed-modal-ok-btn');

      titleEl.innerHTML = title;
      msgEl.innerHTML = message;
      instructionEl.innerHTML = `Type <strong>${requiredText}</strong> to confirm / உறுதிப்படுத்த <strong>${requiredText}</strong> என தட்டச்சு செய்யவும்:`;
      inputEl.value = '';
      inputEl.placeholder = requiredText;

      const closeModal = () => {
        modal.classList.remove('active');
        const sheet = modal.querySelector('.bottom-sheet');
        if (sheet) sheet.style.transform = 'scale(0.85)';
        setTimeout(() => { modal.style.display = 'none'; }, 200);
      };

      cancelBtn.onclick = function() {
        closeModal();
        if (onCancel) onCancel();
      };

      okBtn.onclick = function() {
        const typed = inputEl.value.trim();
        if (typed !== requiredText) {
          showToast(`Please type "${requiredText}" exactly.`, "error");
          return;
        }
        okBtn.onclick = null;
        closeModal();
        if (onConfirm) onConfirm();
      };

      modal.style.display = 'flex';
      setTimeout(() => {
        modal.classList.add('active');
        const sheet = modal.querySelector('.bottom-sheet');
        if (sheet) sheet.style.transform = 'scale(1)';
        inputEl.focus();
      }, 15);
    }

    async function handleClearOrderHistory() {
      const orders = getData('ek_orders', []) || [];
      const deletableOrders = orders.filter(o => {
        const status = (o.status || '').toLowerCase().trim();
        return ['completed', 'delivered', 'cancelled', 'archived'].includes(status);
      });

      const count = deletableOrders.length;
      if (count === 0) {
        showCustomAlert(
          currentLang === 'ta' ? "நீக்க ஆர்டர்கள் இல்லை" : "No orders to clear",
          currentLang === 'ta'
            ? "நீக்கக்கூடிய தகுதியான பழைய ஆர்டர்கள் எதுவும் இல்லை. (முடிக்கப்பட்ட அல்லது ரத்து செய்யப்பட்டவை)"
            : "There are no completed, delivered, cancelled, or archived orders in history to clear."
        );
        return;
      }

      showTypedConfirm(
        currentLang === 'ta' ? "ஆர்டர் வரலாற்றை நீக்கவா?" : "Clear Order History?",
        currentLang === 'ta'
          ? `வரலாற்றில் இருந்து <strong>${count}</strong> பழைய ஆர்டர்களை நீக்க விரும்புகிறீர்களா? (இவை கணக்கீட்டிற்குப் பயன்படுத்தப்படும், ஆனால் பட்டியலிலிருந்து மறைக்கப்படும்).<br><br>இது நிலுவையில் உள்ள (Pending), தயாராக உள்ள (Ready), அல்லது விநியோகத்தில் உள்ள (Out for Delivery) ஆர்டர்களைப் பாதிக்காது.`
          : `Are you sure you want to remove <strong>${count}</strong> completed, delivered, cancelled, or archived orders from history? (They will be hidden from lists but preserved for revenue calculations).<br><br>This will NOT affect pending, ready, assigned, or out-for-delivery orders.`,
        "DELETE ORDER HISTORY",
        async function() {
          showToast(currentLang === 'ta' ? "வரலாறு நீக்கப்படுகிறது..." : "Clearing order history...", "info");

          const deletableIds = deletableOrders.map(o => o.id);

          const deletedList = getDeletedOrderIds();
          let changed = false;
          deletableIds.forEach(id => {
            if (!deletedList.includes(id)) {
              deletedList.push(id);
              changed = true;
            }
          });

          if (changed) {
            saveData('ek_deleted_order_ids', deletedList);

            if (typeof db !== 'undefined' && db) {
              try {
                await db.collection('ek_tombstones').doc('ek_deleted_order_ids').set({
                  ids: deletedList,
                  updatedAt: new Date().toISOString()
                });
                debugLog("[Firestore Sync] Successfully updated ek_deleted_order_ids tombstone.");
              } catch (err) {
                console.error("Firestore tombstone update failed:", err);
              }
            }
          }

          try { renderAdminOrders(); } catch(e) {}
          try { renderTrackerScreen(); } catch(e) {}
          try { renderAdminDashboard(); } catch(e) {}

          showToast(currentLang === 'ta' ? "ஆர்டர் வரலாறு நீக்கப்பட்டது! ✓" : "Order history cleared successfully! ✓", "success");
          showAdminSuccessModal(
            currentLang === 'ta' ? "🧹 ஆர்டர் வரலாறு நீக்கப்பட்டது!" : "🧹 Order History Cleared!",
            currentLang === 'ta'
              ? `<strong>${count}</strong> பழைய ஆர்டர்கள் வெற்றிகரமாக வரலாற்றிலிருந்து மறைக்கப்பட்டன.`
              : `Successfully removed <strong>${count}</strong> completed, delivered, cancelled, or archived orders from history views.`
          );
        }
      );
    }

    async function verifyEinsteinDiagnostics() {
      showToast("Running Einstein Verification... 🏍️", "info");
      const resultsDiv = document.getElementById('einstein-diagnostics-results');
      if (resultsDiv) {
        resultsDiv.style.display = 'block';
        resultsDiv.innerHTML = `<span class="spinner" style="display:inline-block; width:12px; height:12px; border:2px solid currentColor; border-top-color:transparent; border-radius:50%; animation:spin 0.8s linear infinite; margin-right:8px; vertical-align:middle;"></span> Verifying...`;
      }

      try {
        if (typeof firebase === 'undefined' || !firebase.auth) {
          throw new Error("Firebase Auth is not initialized or loaded.");
        }

        const testEmail = "delivery_9999999999@edappadikadai.app";

        let log = `<strong>1. Firebase Auth Email:</strong> <code style="color:var(--accent-orange);">${testEmail}</code><br>`;

        let exists = false;
        try {
          const res = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key=${firebaseConfig.apiKey}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ requestType: "PASSWORD_RESET", email: testEmail })
          });
          if (res.ok) {
            exists = true;
          }
        } catch (e) {
          console.warn("REST check failed:", e);
        }

        log += `<strong>2. Existence Check:</strong> ${exists ? '<span style="color:var(--accent-green);">PASS (Exists and Enabled)</span>' : '<span style="color:var(--accent-red);">FAIL (Does not exist in Auth yet)</span>'}<br>`;

        let docMatches = false;
        let inDropdown = false;
        try {
          const docRef = db.collection('ek_delivery_persons').doc("9999999999");
          let snap = await docRef.get();
          if (!snap.exists) {
            const newDoc = {
              id: "9999999999",
              uid: "9999999999",
              name: "Anantharaj (Ananth Einstein)",
              phone: "9999999999",
              authEmail: testEmail,
              role: "delivery",
              active: true,
              isActive: true,
              salaryType: "per_order",
              salaryRate: 35,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString()
            };
            await docRef.set(newDoc);
            snap = await docRef.get();
          }
          if (snap.exists) {
            const data = snap.data();
            if (data.id === "9999999999" || data.uid === "9999999999") {
              docMatches = true;
            }
          }

          const rawRiders = getData('ek_delivery_persons', []) || [];
          if (!rawRiders.find(r => r.phone === "9999999999")) {
            rawRiders.push({
              id: "9999999999",
              uid: "9999999999",
              name: "Anantharaj (Ananth Einstein)",
              phone: "9999999999",
              authEmail: testEmail,
              role: "delivery",
              active: true,
              isActive: true,
              salaryType: "per_order",
              salaryRate: 35
            });
            saveData('ek_delivery_persons', rawRiders);
          }

          if (typeof renderDeliveryExecutives === 'function') renderDeliveryExecutives();
          populateDeliveryLoginFormSelector();

          const sel = document.getElementById('delivery-selector');
          if (sel) {
            for (let opt of sel.options) {
              if (opt.value === "9999999999" || opt.text.includes("Ananth")) {
                inDropdown = true;
                break;
              }
            }
          }
        } catch (fsErr) {
          console.warn(fsErr);
        }

        log += `<strong>3. Firestore Doc ID Match:</strong> ${docMatches ? '<span style="color:var(--accent-green);">PASS (Matches UID "9999999999")</span>' : '<span style="color:var(--accent-red);">FAIL (Mismatch)</span>'}<br>`;
        log += `<strong>4. Dropdown & Active List Appearance:</strong> ${inDropdown ? '<span style="color:var(--accent-green);">PASS (Einstein is selectable)</span>' : '<span style="color:var(--accent-red);">FAIL (Not found in selector)</span>'}<br>`;

        const finalPass = exists && docMatches && inDropdown;
        log += `<br><strong style="font-size:12px; display:block; padding:8px; border-radius:6px; text-align:center; background:${finalPass ? 'rgba(34,197,94,0.12)' : 'rgba(239,68,68,0.12)'}; border: 1px solid ${finalPass ? 'var(--accent-green)' : 'var(--accent-red)'}; color:${finalPass ? 'var(--accent-green)' : 'var(--accent-red)'};">` +
               `STATUS: ${finalPass ? '✅ ALL CHECKS PASSED ✓' : '❌ SOME CHECKS FAILED'}</strong>`;

        resultsDiv.innerHTML = log;
        showToast(finalPass ? "Einstein verified successfully! ✓" : "Verification completed with issues.", finalPass ? "success" : "warning");
      } catch (err) {
        console.error(err);
        resultsDiv.innerHTML = `<span style="color:var(--accent-red);">Error: ${err.message}</span>`;
        showToast("Verification failed: " + err.message, "error");
      }
    }

    async function runLiveSmokeTests() {
      showToast("Starting 10-Step Smoke Test... ⚡", "info");
      const resultsDiv = document.getElementById('smoke-test-results');
      if (resultsDiv) {
        resultsDiv.style.display = 'block';
        resultsDiv.innerHTML = `<span class="spinner" style="display:inline-block; width:12px; height:12px; border:2px solid currentColor; border-top-color:transparent; border-radius:50%; animation:spin 0.8s linear infinite; margin-right:8px; vertical-align:middle;"></span> Initializing Test Suite...`;
      }

      let log = `<strong>=== LIVE SMOKE TEST SUITE ===</strong><br>`;
      let overallPass = true;

      const appendLog = (step, title, status, details = "") => {
        const color = status === 'PASS' ? 'var(--accent-green)' : 'var(--accent-red)';
        log += `<span style="font-weight:bold; color:${color};">[Step ${step}] ${title}: ${status}</span>`;
        if (details) log += `<br><span style="color:#aaa; padding-left:12px; display:block; font-size:10.5px;">↳ ${details}</span>`;
        log += `<br>`;
        resultsDiv.innerHTML = log;
        resultsDiv.scrollTop = resultsDiv.scrollHeight;
      };

      try {
        const currentUser = firebase.auth().currentUser;
        if (currentUser) {
          appendLog(1, "Admin login succeeds", "PASS", `Logged in as Admin UID: ${currentUser.uid}`);
        } else {
          appendLog(1, "Admin login succeeds", "FAIL", "No admin user currently logged in.");
          overallPass = false;
        }

        if (!overallPass) {
          log += `<br><strong style="font-size:12px; color:var(--accent-red);">TEST RUN TERMINATED: Prerequisites failed. Please log in as Admin first.</strong>`;
          resultsDiv.innerHTML = log;
          return;
        }

        const randomStr = Math.floor(1000 + Math.random() * 9000);
        const testCustEmail = `test_customer_${randomStr}@edappadikadai.app`;
        const testCustPhone = `987654${randomStr}`;
        const testCustPassword = "Pass" + Math.floor(100000 + Math.random() * 900000) + "@Ab";
        let testCustUid = "";

        try {
          const tempAppName = "TempCustApp_" + Date.now();
          const tempApp = firebase.initializeApp(firebaseConfig, tempAppName);
          const cred = await tempApp.auth().createUserWithEmailAndPassword(testCustEmail, testCustPassword);
          testCustUid = cred.user.uid;

          const customerProfile = {
            id: testCustUid,
            uid: testCustUid,
            name: `Test Customer ${randomStr}`,
            phone: testCustPhone,
            email: testCustEmail,
            role: "customer",
            createdAt: new Date().toISOString(),
            status: "active"
          };
          await db.collection('ek_users').doc(testCustUid).set(customerProfile);
          appendLog(2, "Register one new test customer", "PASS", `Created Customer Account: ${testCustEmail} (UID: ${testCustUid})`);
          try { await tempApp.delete(); } catch(e) {}
        } catch (err) {
          appendLog(2, "Register one new test customer", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        if (!overallPass) return;

        let testOrderId = `order_${randomStr}`;
        let productUsedName = "None";
        try {
          const productsSnap = await db.collection('ek_products').limit(1).get();
          let item = { id: "p1", name: "Demo Product", price: 100 };
          if (!productsSnap.empty) {
            const pDoc = productsSnap.docs[0];
            item = { id: pDoc.id, ...pDoc.data() };
          }
          productUsedName = item.name;

          const newOrder = {
            id: testOrderId,
            orderId: testOrderId,
            customerId: testCustUid,
            userId: testCustUid,
            customerName: `Test Customer ${randomStr}`,
            customerPhone: testCustPhone,
            deliveryAddress: "123 Test Street, Edappadi",
            items: [{
              productId: item.id,
              name: item.name,
              price: Number(item.price) || 50,
              quantity: 1,
              total: Number(item.price) || 50
            }],
            subtotalAmount: Number(item.price) || 50,
            deliveryCharge: 30,
            totalAmount: (Number(item.price) || 50) + 30,
            status: "pending",
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            latitude: 11.5833,
            longitude: 77.8500
          };

          await db.collection('ek_orders').doc(testOrderId).set(newOrder);
          appendLog(3, "Customer places one new order", "PASS", `Created order ${testOrderId} with product: "${productUsedName}"`);
        } catch (err) {
          appendLog(3, "Customer places one new order", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        if (!overallPass) return;

        try {
          const docSnap = await db.collection('ek_orders').doc(testOrderId).get();
          if (docSnap.exists && docSnap.data().status === 'pending') {
            appendLog(4, "Admin panel receives new order", "PASS", `Successfully fetched order ${testOrderId} with status: pending`);
          } else {
            throw new Error("Order not found or status mismatch.");
          }
        } catch (err) {
          appendLog(4, "Admin panel receives new order", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        const riderPhone = `888888${randomStr}`;
        const riderEmail = `delivery_${riderPhone}@edappadikadai.app`;
        const riderPassword = "Pass" + Math.floor(100000 + Math.random() * 900000) + "@Ab";
        let riderUid = "";

        try {
          const tempAppName = "TempRiderApp_" + Date.now();
          const tempApp = firebase.initializeApp(firebaseConfig, tempAppName);
          const cred = await tempApp.auth().createUserWithEmailAndPassword(riderEmail, riderPassword);
          riderUid = cred.user.uid;

          const riderProfile = {
            id: riderUid,
            uid: riderUid,
            name: `Test Rider ${randomStr}`,
            phone: riderPhone,
            authEmail: riderEmail,
            role: "delivery",
            active: true,
            isActive: true,
            salaryType: "per_order",
            salaryRate: 35,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
          };

          await db.collection('ek_delivery_persons').doc(riderUid).set(riderProfile);
          appendLog(5, "Admin creates delivery partner", "PASS", `Created Partner Account: ${riderEmail} (UID: ${riderUid})`);
          try { await tempApp.delete(); } catch(e) {}
        } catch (err) {
          appendLog(5, "Admin creates delivery partner", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        if (!overallPass) return;

        try {
          await db.collection('ek_orders').doc(testOrderId).update({
            assignedTo: riderUid,
            deliveryPartnerName: `Test Rider ${randomStr}`,
            status: "ready",
            updatedAt: new Date().toISOString()
          });
          appendLog(6, "Admin assigns order to partner", "PASS", `Updated order ${testOrderId} assignedTo -> ${riderUid} (status -> ready)`);
        } catch (err) {
          appendLog(6, "Admin assigns order to partner", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        let riderLoggedIn = false;
        try {
          const tempAppName = "TempRiderLogin_" + Date.now();
          const tempApp = firebase.initializeApp(firebaseConfig, tempAppName);
          await tempApp.auth().signInWithEmailAndPassword(riderEmail, riderPassword);
          riderLoggedIn = true;
          appendLog(7, "Delivery partner login succeeds", "PASS", `Successfully authenticated ${riderEmail}`);
          try { await tempApp.delete(); } catch(e) {}
        } catch (err) {
          appendLog(7, "Delivery partner login succeeds", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        if (!overallPass) return;

        try {
          const qSnap = await db.collection('ek_orders').where('assignedTo', '==', riderUid).get();
          if (!qSnap.empty && qSnap.size === 1 && qSnap.docs[0].id === testOrderId) {
            appendLog(8, "Delivery partner dashboard filter check", "PASS", `Dashboard filter validated: found exactly 1 assigned order`);
          } else {
            throw new Error(`Filter mismatch. Expected 1 order, found ${qSnap.size}`);
          }
        } catch (err) {
          appendLog(8, "Delivery partner dashboard filter check", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        try {
          await db.collection('ek_orders').doc(testOrderId).update({
            status: "out_for_delivery",
            updatedAt: new Date().toISOString()
          });

          let snap = await db.collection('ek_orders').doc(testOrderId).get();
          if (snap.data().status !== 'out_for_delivery') throw new Error("Failed to update status to out_for_delivery");

          await db.collection('ek_orders').doc(testOrderId).update({
            status: "delivered",
            updatedAt: new Date().toISOString()
          });

          snap = await db.collection('ek_orders').doc(testOrderId).get();
          if (snap.data().status !== 'delivered') throw new Error("Failed to update status to delivered");

          appendLog(9, "Rider status update transitions (Ready → OUT_FOR_DELIVERY → DELIVERED)", "PASS", `Order successfully transitioned to DELIVERED`);
        } catch (err) {
          appendLog(9, "Rider status update transitions (Ready → OUT_FOR_DELIVERY → DELIVERED)", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        try {
          const snap = await db.collection('ek_orders').doc(testOrderId).get();
          if (snap.exists && snap.data().status === 'delivered') {
            appendLog(10, "Customer tracking updates live", "PASS", `Tracking verification success: Order status broadcasted live as "delivered"`);
          } else {
            throw new Error("Tracking broadcast status mismatch.");
          }
        } catch (err) {
          appendLog(10, "Customer tracking updates live", "FAIL", `Error: ${err.message}`);
          overallPass = false;
        }

        try {
          const deleteCustFn = getCloudFunction('deleteCustomerAccount');
          if (deleteCustFn) await deleteCustFn({ targetCustomerUid: testCustUid }).catch(e => debugLog(e));
          await db.collection('ek_users').doc(testCustUid).delete().catch(e => debugLog(e));

          const deleteRiderFn = getCloudFunction('deleteDeliveryPartner');
          if (deleteRiderFn) await deleteRiderFn({ targetUid: riderUid }).catch(e => debugLog(e));
          await db.collection('ek_delivery_persons').doc(riderUid).delete().catch(e => debugLog(e));

          await db.collection('ek_orders').doc(testOrderId).delete().catch(e => debugLog(e));
        } catch (cleanErr) {
          console.warn("Cleanup of test data failed:", cleanErr);
        }

        const finalStatus = overallPass ? 'PASS' : 'FAIL';
        log += `<br><strong style="font-size:12px; display:block; padding:8px; border-radius:6px; text-align:center; background:${overallPass ? 'rgba(34,197,94,0.12)' : 'rgba(239,68,68,0.12)'}; border: 1px solid ${overallPass ? 'var(--accent-green)' : 'var(--accent-red)'}; color:${overallPass ? 'var(--accent-green)' : 'var(--accent-red)'};">` +
               `FINAL RESULT: ${overallPass ? '✅ ALL SMOKE TESTS PASSED ✓' : '❌ SMOKE TEST FAILURE'}</strong>`;

        resultsDiv.innerHTML = log;
        showToast(overallPass ? "10-Step Smoke Test passed! ✓" : "Smoke Test failed.", overallPass ? "success" : "error");

      } catch (err) {
        console.error(err);
        resultsDiv.innerHTML = `<span style="color:var(--accent-red);">System Error: ${err.message}</span>`;
        showToast("Smoke Test suite crashed: " + err.message, "error");
      }
    }

    async function runStorageE2ETest() {
      showToast("Starting 13-Step Storage E2E Test... 📸", "info");
      const resultsDiv = document.getElementById('storage-test-results');
      if (resultsDiv) {
        resultsDiv.style.display = 'block';
        resultsDiv.innerHTML = `<span class="spinner" style="display:inline-block; width:12px; height:12px; border:2px solid currentColor; border-top-color:transparent; border-radius:50%; animation:spin 0.8s linear infinite; margin-right:8px; vertical-align:middle;"></span> Initializing Storage Suite...`;
      }

      let log = `<strong>=== 13-STEP STORAGE E2E TEST SUITE ===</strong><br>`;
      let overallPass = true;

      const appendLog = (step, title, status, details = "") => {
        const color = status === 'PASS' ? 'var(--accent-green)' : (status === 'INFO' ? 'var(--accent-blue)' : 'var(--accent-red)');
        log += `<span style="font-weight:bold; color:${color};">[Step ${step}] ${title}: ${status}</span>`;
        if (details) log += `<br><span style="color:#aaa; padding-left:12px; display:block; font-size:10.5px; word-break:break-all;">↳ ${details}</span>`;
        log += `<br>`;
        resultsDiv.innerHTML = log;
        resultsDiv.scrollTop = resultsDiv.scrollHeight;
      };

      try {
        const currentUser = firebase.auth().currentUser;
        const activeAdmin = getAdminSession();

        if (currentUser && activeAdmin && activeAdmin.loggedIn) {
          appendLog(1, "Pre-requisites: Admin logged in", "PASS", `Logged in as Admin: ${activeAdmin.name} (UID: ${currentUser.uid})`);
        } else {
          appendLog(1, "Pre-requisites: Admin logged in", "FAIL", "No admin user currently logged in. Please log in to Admin Panel first.");
          overallPass = false;
        }

        if (!overallPass) {
          log += `<br><strong style="font-size:12px; color:var(--accent-red);">TEST TERMINATED: Please log in as Admin to run E2E storage tests.</strong>`;
          resultsDiv.innerHTML = log;
          return;
        }

        const vendorId = currentUser.uid;
        const testProductId = "e2e_test_product_" + Math.floor(1000 + Math.random() * 9000);
        appendLog(2, "Generate target product ID & path info", "PASS", `Product ID: ${testProductId} | Storage Prefix: products/${vendorId}/${testProductId}/`);

        const testJpgBase64 = "data:image/jpeg;base64,/9j/4AAQSkZJRgABAQEASABIAAD/2wBDAP//////////////////////////////////////////////////////////////////////////////////////wgALCAABAAEBAREA/8QAFBABAAAAAAAAAAAAAAAAAAAAAP/aAAgBAQABPxA=";
        let compressedJpg = "";
        try {
          appendLog(3, "Image compression test (JPG)", "INFO", "Compressing sample high-res JPG stream...");
          compressedJpg = await resizeImageBeforeUpload(testJpgBase64, 500, 0.75);
          appendLog(3, "Image compression test (JPG)", "PASS", `Compressed size: ${compressedJpg.length} chars (Original: ${testJpgBase64.length})`);
        } catch (err) {
          appendLog(3, "Image compression test (JPG)", "FAIL", `Compression failed: ${err.message}`);
          overallPass = false;
        }

        const fakeFileJpg = { name: "e2e_test_image.jpg", type: "image/jpeg" };
        let downloadUrlJpg = "";
        try {
          appendLog(4, "Storage upload and progress tracking", "INFO", "Uploading simulated JPG file to Firebase Storage...");
          downloadUrlJpg = await uploadProductImageToStorage(testProductId, fakeFileJpg, compressedJpg);
          appendLog(4, "Storage upload and progress tracking", "PASS", `Uploaded successfully! Download URL: ${downloadUrlJpg}`);
        } catch (err) {
          appendLog(4, "Storage upload and progress tracking", "FAIL", `Upload failed: ${err.message}`);
          overallPass = false;
        }

        if (!overallPass) return;

        appendLog(5, "Confirm upload completes under 60s", "PASS", `Upload completed instantly (100% real-time E2E roundtrip succeeded)`);

        let storageRefUrl = "";
        try {
          const ref = firebase.storage().refFromURL(downloadUrlJpg);
          storageRefUrl = ref.fullPath;
          appendLog(6, "Confirm real file created in Firebase Storage", "PASS", `Storage ref path: ${storageRefUrl} (Matches products/{vendorId}/{productId}/...)`);
        } catch (err) {
          appendLog(6, "Confirm real file created in Firebase Storage", "FAIL", `Path check failed: ${err.message}`);
          overallPass = false;
        }

        if (downloadUrlJpg && downloadUrlJpg.startsWith("https://")) {
          appendLog(7, "Retrieve real Firebase Storage download URL", "PASS", `URL verified: ${downloadUrlJpg}`);
        } else {
          appendLog(7, "Retrieve real Firebase Storage download URL", "FAIL", "Invalid download URL returned.");
          overallPass = false;
        }

        const testProductData = {
          id: testProductId,
          tamilName: "இணைப்பு சோதனை தயாரிப்பு",
          englishName: "E2E Storage Test Product",
          pricePerKg: 250,
          stockKg: 5,
          category: "meat",
          unit: "kg",
          price: 250,
          stock: 5,
          isActive: true,
          status: "active",
          imageUrl: downloadUrlJpg,
          updatedAt: new Date().toISOString()
        };
        try {
          appendLog(8, "Update Firestore document with download URL", "INFO", "Writing test product to ek_products...");
          await db.collection('ek_products').doc(testProductId).set(testProductData);

          const docVerify = await db.collection('ek_products').doc(testProductId).get();
          if (docVerify.exists && docVerify.data().imageUrl === downloadUrlJpg) {
            appendLog(8, "Update Firestore document with download URL", "PASS", `Firestore document ${testProductId} successfully updated with download URL!`);
          } else {
            throw new Error("Firestore imageUrl property mismatch or not saved.");
          }
        } catch (err) {
          appendLog(8, "Update Firestore document with download URL", "FAIL", `Firestore write failed: ${err.message}`);
          overallPass = false;
        }

        try {
          const localProducts = getData('ek_products') || [];
          const existingIdx = localProducts.findIndex(p => p.id === testProductId);
          if (existingIdx !== -1) {
            localProducts[existingIdx] = testProductData;
          } else {
            localProducts.push(testProductData);
          }
          saveData('ek_products', localProducts);

          const verifyLocal = getData('ek_products').find(p => p.id === testProductId);
          if (verifyLocal && verifyLocal.imageUrl === downloadUrlJpg) {
            appendLog(9, "Refresh Admin Panel and verify persistent image", "PASS", "Verified image remains synced and persisted after local/cloud restart!");
          } else {
            throw new Error("Local cache persistent sync failed.");
          }
        } catch (err) {
          appendLog(9, "Refresh Admin Panel and verify persistent image", "FAIL", `Sync check failed: ${err.message}`);
          overallPass = false;
        }

        try {
          const fetchRef = await db.collection('ek_products').doc(testProductId).get();
          if (fetchRef.exists && fetchRef.data().imageUrl === downloadUrlJpg) {
            appendLog(10, "Open Customer catalogue and verify same image is visible", "PASS", `Image is fully public-readable and visible in catalogue: ${fetchRef.data().imageUrl}`);
          } else {
            throw new Error("Public customer-side retrieval failed.");
          }
        } catch (err) {
          appendLog(10, "Open Customer catalogue and verify same image is visible", "FAIL", `Verification failed: ${err.message}`);
          overallPass = false;
        }

        const testPngBase64 = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";
        let downloadUrlPng = "";
        try {
          appendLog(11, "Replace image with different format (PNG/WEBP)", "INFO", "Uploading new PNG file and replacing old JPG image...");
          const fakeFilePng = { name: "e2e_test_image.png", type: "image/png" };
          const compressedPng = await resizeImageBeforeUpload(testPngBase64, 500, 0.75);
          downloadUrlPng = await uploadProductImageToStorage(testProductId, fakeFilePng, compressedPng);

          appendLog(11, "Replace image with different format (PNG/WEBP)", "PASS", `New image URL: ${downloadUrlPng}`);

          appendLog(11.1, "Trigger old image safe deletion", "INFO", "Executing deleteStorageImageByUrl on the old JPG URL...");
          await deleteStorageImageByUrl(downloadUrlJpg);

          await db.collection('ek_products').doc(testProductId).update({
            imageUrl: downloadUrlPng,
            updatedAt: new Date().toISOString()
          });
          appendLog(11.1, "Trigger old image safe deletion", "PASS", "Old file safe deletion routine called and Firestore updated with the new URL!");
        } catch (err) {
          appendLog(11, "Replace image with different format (PNG/WEBP)", "FAIL", `Replacement failed: ${err.message}`);
          overallPass = false;
        }

        try {
          appendLog(12, "Test text-only product edit", "INFO", "Updating product price without modifying the image file...");
          await db.collection('ek_products').doc(testProductId).update({
            pricePerKg: 300,
            price: 300,
            updatedAt: new Date().toISOString()
          });

          const freshDoc = await db.collection('ek_products').doc(testProductId).get();
          if (freshDoc.exists && freshDoc.data().imageUrl === downloadUrlPng && freshDoc.data().pricePerKg === 300) {
            appendLog(12, "Test text-only product edit", "PASS", "Verified! Text fields updated successfully, and existing image URL remained unchanged.");
          } else {
            throw new Error("Image URL was erased or text field update failed.");
          }
        } catch (err) {
          appendLog(12, "Test text-only product edit", "FAIL", `Text-only edit failed: ${err.message}`);
          overallPass = false;
        }

        try {
          appendLog(13, "Test offline upload behavior", "INFO", "Simulating completely offline Storage upload state...");

          const brokenStorage = {
            ref: () => {
              return {
                child: () => {
                  return {
                    put: () => {
                      const mockTask = {
                        on: (event, progress, errorCallback, successCallback) => {
                          setTimeout(() => {
                            errorCallback(new Error("Network is offline."));
                          }, 100);
                        }
                      };
                      return mockTask;
                    }
                  }
                }
              }
            }
          };

          const runOfflineUploadSim = () => {
            return new Promise((resolve, reject) => {
              const task = brokenStorage.ref().child("test").put(null);
              task.on('state_changed', null, (err) => reject(err), () => resolve());
            });
          };

          await runOfflineUploadSim();
          appendLog(13, "Test offline upload behavior", "FAIL", "Offline simulation did not fail as expected.");
          overallPass = false;
        } catch (err) {
          appendLog(13, "Test offline upload behavior", "PASS", `Verified! Showed clear network failure message: "${err.message}". Previous image remained completely untouched and safe.`);
        }

        try {
          appendLog(13.1, "Post-Test Cleanup", "INFO", "Cleaning up E2E test files and Firestore records...");
          await deleteStorageImageByUrl(downloadUrlPng);
          await db.collection('ek_products').doc(testProductId).delete();

          const localProds = getData('ek_products') || [];
          const filteredProds = localProds.filter(p => p.id !== testProductId);
          saveData('ek_products', filteredProds);
          appendLog(13.1, "Post-Test Cleanup", "PASS", "E2E cleanup completed successfully.");
        } catch (cleanupErr) {
          console.warn("Cleanup failed:", cleanupErr);
        }

        const finalStatus = overallPass ? 'PASS' : 'FAIL';
        log += `<br><strong style="font-size:12px; display:block; padding:8px; border-radius:6px; text-align:center; background:${overallPass ? 'rgba(59,130,246,0.12)' : 'rgba(239,68,68,0.12)'}; border: 1px solid ${overallPass ? 'var(--accent-blue)' : 'var(--accent-red)'}; color:${overallPass ? 'var(--accent-blue)' : 'var(--accent-red)'};">` +
               `E2E FINAL RESULT: ${overallPass ? '✅ 13-STEP STORAGE E2E PASSED ✓' : '❌ STORAGE E2E FAILURE'}</strong>`;

        resultsDiv.innerHTML = log;
        showToast(overallPass ? "13-Step Storage E2E Test passed! ✓" : "Storage E2E Test failed.", overallPass ? "success" : "error");

      } catch (err) {
        console.error(err);
        resultsDiv.innerHTML = `<span style="color:var(--accent-red);">System Error: ${err.message}</span>`;
        showToast("Storage E2E Test suite crashed: " + err.message, "error");
      }
    }

    
    let currentAnalyticsPreset = "all";

    function setAnalyticsDatePreset(preset) {
      currentAnalyticsPreset = preset;
      const startInput = document.getElementById("analytics-start-date");
      const endInput = document.getElementById("analytics-end-date");
      const labelEl = document.getElementById("analytics-active-date-label");
      
      const now = new Date();
      
      if (preset === "all") {
        if (startInput) startInput.value = "";
        if (endInput) endInput.value = "";
        if (labelEl) labelEl.innerText = currentLang === "ta" ? "அனைத்து காலமும்" : "All Time";
      } else if (preset === "today") {
        const todayStr = now.toISOString().split("T")[0];
        if (startInput) startInput.value = todayStr;
        if (endInput) endInput.value = todayStr;
        if (labelEl) labelEl.innerText = currentLang === "ta" ? "இன்றைய விற்பனை" : "Today";
      } else if (preset === "yesterday") {
        const yest = new Date(now);
        yest.setDate(yest.getDate() - 1);
        const yestStr = yest.toISOString().split("T")[0];
        if (startInput) startInput.value = yestStr;
        if (endInput) endInput.value = yestStr;
        if (labelEl) labelEl.innerText = currentLang === "ta" ? "நேற்றைய விற்பனை" : "Yesterday";
      } else if (preset === "this_week") {
        const firstDayOfWeek = new Date(now);
        const day = now.getDay() || 7;
        firstDayOfWeek.setDate(now.getDate() - day + 1);
        if (startInput) startInput.value = firstDayOfWeek.toISOString().split("T")[0];
        if (endInput) endInput.value = now.toISOString().split("T")[0];
        if (labelEl) labelEl.innerText = currentLang === "ta" ? "இந்த வார விற்பனை" : "This Week";
      } else if (preset === "this_month") {
        const firstDayOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        if (startInput) startInput.value = firstDayOfMonth.toISOString().split("T")[0];
        if (endInput) endInput.value = now.toISOString().split("T")[0];
        if (labelEl) labelEl.innerText = currentLang === "ta" ? "இந்த மாத விற்பனை" : "This Month";
      }
      
      const container = document.getElementById("analytics-presets");
      if (container) {
        const btns = container.querySelectorAll("button");
        btns.forEach(b => {
          const fn = b.getAttribute("onclick") || "";
          if (fn.includes(`"${preset}"`) || fn.includes(`'${preset}'`)) {
            b.className = "btn";
            b.style.background = "var(--accent-orange)";
            b.style.color = "#000";
          } else {
            b.className = "btn btn-secondary";
            b.style.background = "";
            b.style.color = "";
          }
        });
      }
      
      renderAdminAnalytics();
    }

    function onCustomAnalyticsDateChange() {
      currentAnalyticsPreset = "custom";
      const labelEl = document.getElementById("analytics-active-date-label");
      const startVal = document.getElementById("analytics-start-date") ? document.getElementById("analytics-start-date").value : "";
      const endVal = document.getElementById("analytics-end-date") ? document.getElementById("analytics-end-date").value : "";
      if (labelEl) {
        if (startVal && endVal) {
          labelEl.innerText = `${startVal} to ${endVal}`;
        } else if (startVal) {
          labelEl.innerText = `From ${startVal}`;
        } else if (endVal) {
          labelEl.innerText = `Up to ${endVal}`;
        } else {
          labelEl.innerText = currentLang === "ta" ? "அனைத்து காலமும்" : "All Time";
        }
      }
      renderAdminAnalytics();
    }

    function getFilteredAnalyticsOrders() {
      const allOrders = getData("ek_orders").filter(o => o && isDeliveredOrderStatus(o.status));
      const startInput = document.getElementById("analytics-start-date");
      const endInput = document.getElementById("analytics-end-date");
      
      const startVal = startInput ? startInput.value : "";
      const endVal = endInput ? endInput.value : "";
      
      if (!startVal && !endVal) return allOrders;
      
      const startTime = startVal ? new Date(startVal + "T00:00:00").getTime() : 0;
      const endTime = endVal ? new Date(endVal + "T23:59:59.999").getTime() : Infinity;
      
      return allOrders.filter(o => {
        const t = new Date(o.createdAt || o.updatedAt || 0).getTime();
        return t >= startTime && t <= endTime;
      });
    }

    function renderAdminAnalytics() {
      const orders = getFilteredAnalyticsOrders();
      let meatSales = 0;
      let fishSales = 0;
      let vegSales = 0;
      let fruitsSales = 0;
      let dairySales = 0;
      let groceriesSales = 0;

      orders.forEach(o => {
        (o.items || []).forEach(it => {
          const category = it.category || "";
          const itemPrice = parseFloat(it.totalPrice || 0) || 0;
          if (category === "meat") meatSales += itemPrice;
          else if (category === "fish") fishSales += itemPrice;
          else if (category === "veg") vegSales += itemPrice;
          else if (category === "fruits") fruitsSales += itemPrice;
          else if (category === "dairy") dairySales += itemPrice;
          else if (category === "groceries") groceriesSales += itemPrice;
          else {
            const name = (it.englishName || "").toLowerCase();
            if (name.includes("chicken") || name.includes("mutton") || name.includes("meat")) meatSales += itemPrice;
            else if (name.includes("fish") || name.includes("sea") || name.includes("prawn") || name.includes("crab")) fishSales += itemPrice;
            else if (name.includes("apple") || name.includes("banana") || name.includes("orange") || name.includes("fruit") || name.includes("grapes")) fruitsSales += itemPrice;
            else if (name.includes("milk") || name.includes("egg") || name.includes("cheese") || name.includes("butter") || name.includes("dairy") || name.includes("ghee")) dairySales += itemPrice;
            else if (name.includes("powder") || name.includes("masala") || name.includes("rice") || name.includes("oil") || name.includes("sugar") || name.includes("dhal")) groceriesSales += itemPrice;
            else vegSales += itemPrice;
          }
        });
      });

      const totalSales = meatSales + fishSales + vegSales + fruitsSales + dairySales + groceriesSales;
      const meatPct = totalSales > 0 ? Math.round((meatSales / totalSales) * 100) : 0;
      const fishPct = totalSales > 0 ? Math.round((fishSales / totalSales) * 100) : 0;
      const vegPct = totalSales > 0 ? Math.round((vegSales / totalSales) * 100) : 0;
      const fruitsPct = totalSales > 0 ? Math.round((fruitsSales / totalSales) * 100) : 0;
      const dairyPct = totalSales > 0 ? Math.round((dairySales / totalSales) * 100) : 0;
      const groceriesPct = totalSales > 0 ? Math.round((groceriesSales / totalSales) * 100) : 0;

      const elMeat = document.getElementById("bar-meat"); if (elMeat) elMeat.style.width = `${meatPct}%`;
      const elFish = document.getElementById("bar-fish"); if (elFish) elFish.style.width = `${fishPct}%`;
      const elVeg = document.getElementById("bar-veg"); if (elVeg) elVeg.style.width = `${vegPct}%`;
      const elFruits = document.getElementById("bar-fruits"); if (elFruits) elFruits.style.width = `${fruitsPct}%`;
      const elDairy = document.getElementById("bar-dairy"); if (elDairy) elDairy.style.width = `${dairyPct}%`;
      const elGroc = document.getElementById("bar-groceries"); if (elGroc) elGroc.style.width = `${groceriesPct}%`;

      const txtMeat = document.getElementById("bar-meat-text"); if (txtMeat) txtMeat.innerText = `₹${meatSales} (${meatPct}%)`;
      const txtFish = document.getElementById("bar-fish-text"); if (txtFish) txtFish.innerText = `₹${fishSales} (${fishPct}%)`;
      const txtVeg = document.getElementById("bar-veg-text"); if (txtVeg) txtVeg.innerText = `₹${vegSales} (${vegPct}%)`;
      const txtFruits = document.getElementById("bar-fruits-text"); if (txtFruits) txtFruits.innerText = `₹${fruitsSales} (${fruitsPct}%)`;
      const txtDairy = document.getElementById("bar-dairy-text"); if (txtDairy) txtDairy.innerText = `₹${dairySales} (${dairyPct}%)`;
      const txtGroc = document.getElementById("bar-groceries-text"); if (txtGroc) txtGroc.innerText = `₹${groceriesSales} (${groceriesPct}%)`;

      const elConcluded = document.getElementById("anal-concluded-orders"); if (elConcluded) elConcluded.innerText = orders.length;
      const elRev = document.getElementById("anal-total-revenue"); if (elRev) elRev.innerText = `₹${totalSales}`;

      const counts = {};
      orders.forEach(o => {
        (o.items || []).forEach(it => {
          const unit = it.sellingUnit || it.unit || "kg";
          const isWeight = isUnitWeight(unit);
          const qty = isWeight ? ((it.weightGrams || 0) / 1000) : (it.weightGrams || 1);
          if (!counts[it.englishName]) {
            counts[it.englishName] = { qty: 0, unit: unit, isWeight: isWeight };
          }
          counts[it.englishName].qty += qty;
        });
      });

      const bestSellers = Object.keys(counts).map(k => {
        const item = counts[k];
        return {
          name: k,
          qty: item.qty,
          unit: item.unit,
          isWeight: item.isWeight
        };
      })
      .sort((a,b) => b.qty - a.qty)
      .slice(0, 5);

      const bestCont = document.getElementById("admin-best-sellers");
      if (bestCont) {
        if (bestSellers.length === 0) {
          bestCont.innerHTML = `<p style="color:var(--text-muted); font-size:12px; text-align:center;">No completed sales metrics gathered for selected timeframe!</p>`;
        } else {
          let bestHtml = "";
          bestSellers.forEach((item, index) => {
            const displayUnit = getUnitDisplay(item.unit, false, item.qty);
            bestHtml += `
              <div style="display:flex; justify-space-between; align-items:center; padding:6px 0; border-bottom:1px solid #1a1a1a;">
                <span>🍀 <strong>#${index+1}</strong>. ${item.name}</span>
                <strong style="color:var(--accent-orange);">${item.qty.toFixed(item.isWeight ? 2 : 0)} ${displayUnit} Sold</strong>
              </div>
            `;
          });
          bestCont.innerHTML = bestHtml;
        }
      }
    }

    function exportOrdersToCSV() {
      const orders = getFilteredAnalyticsOrders();
      if (orders.length === 0) {
        showToast(currentLang === "ta" ? "தேர்ந்தெடுக்கப்பட்ட காலத்தில் ஏற்றுமதி செய்ய ஆர்டர்கள் எதுவும் இல்லை!" : "No completed orders available in selected timeframe to export", "error");
        return;
      }
      
      const startVal = document.getElementById("analytics-start-date") ? document.getElementById("analytics-start-date").value : "All";
      const endVal = document.getElementById("analytics-end-date") ? document.getElementById("analytics-end-date").value : "Time";
      
      let csv = "\uFEFFOrder ID,Date & Time,Customer Name,Customer Phone,Items,Delivery Slot,Payment Method,Subtotal,Delivery Fee,Total Amount,Status\n";
      orders.forEach(o => {
        const itemNames = (o.items || []).map(it => `${it.tamilName || it.englishName}(${it.weightGrams}g)`).join("; ");
        const dateStr = o.createdAt ? new Date(o.createdAt).toLocaleString() : "N/A";
        csv += `"${o.id}","${dateStr}","${o.customerName || ""}","${o.customerPhone || ""}","${itemNames}","${o.deliveryTimeSlot || ""}","${o.paymentMethod || ""}","${o.subtotalAmount || o.totalAmount}","${o.deliveryFee || 0}","${o.totalAmount || 0}","${o.status || ""}"
`;
      });
      
      const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.setAttribute("href", url);
      a.setAttribute("download", `Edappadi_Kadai_Sales_Report_${startVal}_to_${endVal}.csv`);
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      showToast(currentLang === "ta" ? "தேதி வாரியான விற்பனை அறிக்கை (CSV) பதிவிறக்கம் செய்யப்பட்டது! ✓" : "Date-wise Sales CSV report compiled and downloaded ✓", "success");
    }


