    window.onboardingTargetDestination = null;

    function checkAndShowOnboardingFlow(targetScreenFunc) {
      window.onboardingTargetDestination = targetScreenFunc;
      localStorage.setItem('ek_permissions_onboarded', 'true');

      // Request native Android permissions directly if AndroidStorage bridge is available
      if (typeof AndroidStorage !== 'undefined') {
        try {
          if (!AndroidStorage.hasNotificationPermission()) {
            AndroidStorage.requestNotificationPermission();
          }
        } catch (e) {
          console.warn("[Permissions] Notification request error:", e);
        }
        try {
          if (!AndroidStorage.hasLocationPermission()) {
            AndroidStorage.requestLocationPermission();
          }
        } catch (e) {
          console.warn("[Permissions] Location request error:", e);
        }
      }

      // Proceed immediately to target screen (e.g. Home screen) without showing custom onboarding page
      if (typeof targetScreenFunc === 'function') {
        targetScreenFunc();
      }
    }

